INSERT INTO `users` (`id`, `email`, `full_name`, `role`, `cefr_level`, `subscription_status`, `subscription_tier`, `subscription_expires_at`)
INSERT INTO `curriculum_modules` (`id`, `number`, `title_en`, `title_ar`, `cefr_range`, `color`, `description_en`, `description_ar`) VALUES ('mod-1', 1, 'Essential English for Classroom Instructions', 'اللغة الإنجليزية الأساسية لإعطاء التعليمات الصفية', 'A1–B1', '#E50914', 'Master crisp classroom routines, imperative staging, instruction-checking questions (ICQs), and smooth lesson transitions to maximize student talk time.', 'إتقان الروتين الصفي وصياغة التعليمات المباشرة وأسئلة التحقق (ICQs) والانتقالات السلسة لتقليل وقت حديث المعلم ومضاعفة تحدث الطلاب.');
INSERT INTO `lessons` (`id`, `module_id`, `number`, `slug`, `cefr`, `duration_min`, `title_en`, `title_ar`, `subtitle_en`, `subtitle_ar`, `pedagogical_overview_en`, `pedagogical_overview_ar`, `is_free_preview`) VALUES ('les-1-1', 'mod-1', '1.1', 'greeting-attendance', 'A1', 15, 'Greeting & Attendance', 'التحية وتفقد الحضور والغياب', 'Establishing positive rapport and efficient roll-call routines in English', 'بناء الألفة الإيجابية وتطبيق روتين تفقد الحضور باللغة الإنجليزية', 'Starting the lesson decisively in English sets the cognitive tone. Jeremy Harmer emphasizes that the first two minutes establish classroom authority and mutual rapport. Avoid greeting in Arabic; use welcoming body language and predictable greeting patterns.', 'بداية الحصة بالحزم والود باللغة الإنجليزية يحدد المسار اللغوي للحصة بأكملها. يوضح جيريمي هارمر أن أول دقيقتين تبنيان الألفة والسلطة التربوية. تجنب التحدث بالعربية واستخدم لغة جسد مرحبة مع روتين تفقد حضور سريع.', 1);
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-1-1', 'roll call', '/ˈroʊl ˌkɔːl/', 'تفقد الحضور والغياب', 'Let\'s quickly do the roll call.', 'دعونا نأخذ تفقد الحضور سريعاً.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-1-1', 'absent', '/ˈæb.sənt/', 'غائب', 'Who is absent today?', 'من الغائب اليوم؟');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-1-1', 'present', '/ˈprez.ənt/', 'حاضر', 'Please say \"present\" when I call your name.', 'رجاءً قولوا \"حاضر\" عند مناداة أسمائكم.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-1-1', 'settle down', '/ˈset.əl daʊn/', 'اهدأوا واستقروا في مقاعدكم', 'Settle down everyone, take your seats.', 'اهدأوا جميعاً واجلسوا في أماكنكم.');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-1-1-1', 'les-1-1', 'Good morning everyone! Please take your seats and get ready.', 'صباح الخير جميعاً! رجاءً اجلسوا في مقاعدكم واستعدوا.', '/ɡʊd ˈmɔːr.nɪŋ ˈev.ri.wʌn/', 'Warm whole-class greeting establishing readiness.', 'تحية ترحيبية جامعة تنبه الطلاب لبدء الحصة.', 'instruction');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-1-1-2', 'les-1-1', 'Who is absent today? Is anyone missing from this row?', 'من الغائب اليوم؟ هل ينقصنا أحد في هذا الصف؟', '/huː ɪz ˈæb.sənt təˈdeɪ/', 'Peer-involved attendance check saving teacher time.', 'تفقد الحضور بمشاركة الزملاء لاختصار الوقت.', 'questioning');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-1-1-3', 'les-1-1', 'Glad to see you all back. How was your weekend, Sarah?', 'سعيد برؤيتكم جميعاً من جديد. كيف كانت عطلة نهاية الأسبوع يا سارة؟', '/ɡlæd tuː siː juː ɔːl bæk/', 'Micro-rapport builder before diving into formal content.', 'بناء جسر تواصل إنساني وسريع قبل بدء المحتوى الأكاديمي.', 'transition');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-1', 1, 'Teacher', 'المعلم', 'Good morning class! Settle down and take your seats, please.', 'صباح الخير يا طلاب! اهدأوا واجلسوا في أماكنكم من فضلكم.');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-1', 2, 'Class', 'الفصل', 'Good morning, Mr. Ahmed!', 'صباح الخير يا أستاذ أحمد!');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-1', 3, 'Teacher', 'المعلم', 'Wonderful. Let us take attendance quickly. Ziad?', 'رائع. دعونا نأخذ الحضور سريعاً. زياد؟');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-1', 4, 'Student', 'طالب', 'Present, teacher!', 'حاضر يا أستاذ!');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-1', 5, 'Teacher', 'المعلم', 'Laila? Has anyone seen Laila this morning?', 'ليلى؟ هل رأى أحد ليلى هذا الصباح؟');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-1', 6, 'Student', 'طالب', 'She is absent today, she has a cold.', 'إنها غائبة اليوم، أصيبت بنزلة برد.');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-1', 7, 'Teacher', 'المعلم', 'I hope she gets well soon. Now everyone, books closed, eyes on the board!', 'أتمنى لها الشفاء العاجل. والآن جميعاً، الكتب مغلقة، وعيونكم على السبورة!');
INSERT INTO `exercises` (`id`, `lesson_id`, `prompt_en`, `prompt_ar`, `context_en`, `context_ar`, `explanation_en`, `explanation_ar`, `source_reference`) VALUES ('ex-1-1-1', 'les-1-1', 'Which phrase is the most natural and efficient way to begin attendance in an English classroom?', 'أي العبارات التالية هي الأكثر طبيعية وكفاءة لبدء تفقد الحضور في الفصل باللغة الإنجليزية؟', 'You enter the room and need to check who is present within 60 seconds.', 'دخلت الفصل وتريد التحقق من الحضور في غضون دقيقة واحدة.', 'Saying \"Let’s quickly take the roll call. Please say present...\" is standard pedagogical English and gives immediate operational clarity.', 'عبارة \"Let’s quickly take the roll call...\" هي الصيغة التربوية المعيارية وتحدد بوضوح الاستجابة المطلوبة من الطلاب.', 'Jim Scrivener, Classroom Management Techniques (Cambridge, 2012)');
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-1', 'ex-1-1-1', 'Who is not coming today to school?', 'من لم يأت اليوم للمدرسة؟', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-2', 'ex-1-1-1', 'Let’s quickly take the roll call. Please say \"present\" when you hear your name.', 'دعونا نأخذ تفقد الحضور سريعاً. رجاءً قولوا \"حاضر\" عند سماع أسمائكم.', 1);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-3', 'ex-1-1-1', 'Write your names on a paper and give it to me now.', 'اكتبوا أسمائكم في ورقة وسلموها لي الآن.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-4', 'ex-1-1-1', 'Are all of you present here today or not?', 'هل كلكم حاضرون هنا اليوم أم لا؟', 0);
INSERT INTO `assignments` (`id`, `lesson_id`, `title_en`, `title_ar`, `instructions_en`, `instructions_ar`) VALUES ('asgn-les-1-1', 'les-1-1', 'Morning Routine Audio Recording', 'تسجيل صوتي لروتين افتتاح الحصة وتفقد الحضور', 'Record a 60-second audio clip greeting an imaginary grade 7 class, settling them down, and checking attendance using at least 3 taught phrases.', 'سجل مقطعاً صوتياً مدته 60 ثانية تحيي فيه فصلاً افتراضياً وتضبط هدوءهم وتتفقد الحضور باستخدام 3 عبارات على الأقل من الدرس.');
INSERT INTO `lessons` (`id`, `module_id`, `number`, `slug`, `cefr`, `duration_min`, `title_en`, `title_ar`, `subtitle_en`, `subtitle_ar`, `pedagogical_overview_en`, `pedagogical_overview_ar`, `is_free_preview`) VALUES ('les-1-2', 'mod-1', '1.2', 'giving-instructions', 'A2', 20, 'Giving Instructions', 'إعطاء التعليمات الصفية المباشرة والمرحلية', 'Scrivener’s staged instruction model and minimizing Teacher Talking Time (TTT)', 'نموذج سكريـفنـر للمراحل المتسلسلة وتقليل وقت حديث المعلم الزائد', 'Research shows over 70\% of classroom confusion stems from instructions delivered while students are distracted by papers. Always secure eye contact, state the instruction in 10 words or fewer, verify understanding, and only then hand out tasks.', 'تشير الدراسات إلى أن أكثر من 70\% من ارتباك الطلاب ينشأ عند إعطاء التعليمات أثناء تصفح الطلاب للأوراق. احرص دائماً على جذب النظرات، وقدم التعليمة في أقل من 10 كلمات، ثم وزع المهام.', 0);
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-1-2', 'in pairs', '/ɪn ˈpeərz/', 'في أزواج / كل اثنين معاً', 'Work in pairs with your shoulder partner.', 'اعملوا في أزواج مع زميلكم المجاور.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-1-2', 'hand out', '/hænd aʊt/', 'يوزّع أوراقاً أو أدوات', 'Please help me hand out the worksheets.', 'من فضلك ساعدني في توزيع أوراق العمل.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-1-2', 'underline', '/ˌʌn.dəˈlaɪn/', 'يضع خطاً تحت', 'Underline all action verbs in paragraph one.', 'ضعوا خطاً تحت جميع أفعال الحركة في الفقرة الأولى.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-1-2', 'time limit', '/ˈtaɪm ˌlɪm.ɪt/', 'المهلة الزمنية المحددة', 'You have a three-minute time limit.', 'لديكم مهلة زمنية قدرها ثلاث دقائق.');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-1-2-1', 'les-1-2', 'First, read silently. Next, compare with your partner. You have three minutes.', 'أولاً، اقرأوا بصمت. ثانياً، قارنوا مع زميلكم. لديكم ثلاث دقائق.', '/fɜːrst riːd ˈsaɪ.lənt.li/', 'Sequenced 3-part instruction with explicit time parameter.', 'تعليمة ثلاثية مرحلية مع تحديد صارم ومطمئن للوقت.', 'instruction');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-1-2-2', 'les-1-2', 'Do not write yet. Just listen to the recording.', 'لا تكتبوا بعد. استمعوا فقط إلى المقطع الصوتي.', '/duː nɒt raɪt jɛt/', 'Negative constraint preventing premature task execution.', 'تنبيه استباقي يمنع انصراف الطلاب للكتابة قبل الاستماع.', 'instruction');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-1-2-3', 'les-1-2', 'Turn to page 42, exercise 3. Pens down until I say go.', 'افتحوا صفحة 42، التمرين 3. ضعوا الأقلام جانباً حتى أعطي إشارة البدء.', '/tɜːrn tuː peɪdʒ fɔːr.ti tuː/', 'Pre-task physical constraint maintaining collective attention.', 'توجيه جسدي (وضع الأقلام) يضمن استماع الجميع قبل التنفيذ.', 'management');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-2', 1, 'Teacher', 'المعلم', 'Eyes up front, pens on your desks, please.', 'انظروا للأمام، وضعوا الأقلام على المكاتب من فضلكم.');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-2', 2, 'Class', 'الفصل', '(Silence, students look at the teacher)', '(صمت، وينظر الطلاب إلى المعلم)');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-2', 3, 'Teacher', 'المعلم', 'Open page 24. Exercise B. You will work in pairs. Underline the past verbs. Three minutes. Go!', 'افتحوا صفحة 24. تمرين B. ستعملون في أزواج. ضعوا خطاً تحت أفعال الماضي. ثلاث دقائق. ابدأوا!');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-2', 4, 'Student A', 'طالب أ', 'Teacher, do we write the meanings?', 'أستاذ، هل نكتب المعاني؟');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-2', 5, 'Teacher', 'المعلم', 'No, only underline the verbs. Start now!', 'كلا، فقط ضعوا خطاً تحت الأفعال. ابدأوا الآن!');
INSERT INTO `exercises` (`id`, `lesson_id`, `prompt_en`, `prompt_ar`, `context_en`, `context_ar`, `explanation_en`, `explanation_ar`, `source_reference`) VALUES ('ex-1-2-1', 'les-1-2', 'Which instruction is the most effective in reducing confusion according to CELTA standards?', 'أي التعليمات التالية هي الأكثر فاعلية في القضاء على الارتباك وفق معايير CELTA؟', 'You want students to read a text and answer 3 questions in pairs.', 'تريد من الطلاب قراءة نص والإجابة عن 3 أسئلة في أزواج.', 'Numbered stages with explicit action verbs and a clear time limit remove cognitive overload.', 'ترقيم المراحل وتحديد مدة زمنية محددة يزيل التشتت الذهني ويوضح المطلوب بدقة متناهية.', 'Jim Scrivener, Learning Teaching (Macmillan, 2011)');
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-1', 'ex-1-2-1', 'Now guys I think you should probably read page 20 and talk to your friend about question 1, 2, 3 if you have time.', 'صياغة مطولة ومترددة مليئة بالحشو اللغوي.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-2', 'ex-1-2-1', 'Step 1: Read page 20 alone. Step 2: Answer questions 1 to 3 with your partner. Four minutes. Start!', 'خطوة 1: اقرأوا بمفردكم. خطوة 2: أجيبوا مع زميلكم. أربع دقائق. ابدأوا!', 1);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-3', 'ex-1-2-1', 'Who wants to read page 20 and do some work together right now?', 'من يحب أن يقرأ صفحة 20 ويعمل سوياً؟', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-4', 'ex-1-2-1', 'Look at the book and answer.', 'انظروا للكتاب وأجيبوا.', 0);
INSERT INTO `assignments` (`id`, `lesson_id`, `title_en`, `title_ar`, `instructions_en`, `instructions_ar`) VALUES ('asgn-les-1-2', 'les-1-2', 'Instruction Staging Blueprint', 'مخطط صياغة التعليمات المرحلية', 'Write the exact script of instructions you would deliver for a 5-minute reading comprehension activity in no more than 4 bullet points.', 'اكتب النص الحرفي للتعليمات التي ستلقيها لنشاط قراءة مدته 5 دقائق في موعد أقصاه 4 نقاط مختصرة.');
INSERT INTO `lessons` (`id`, `module_id`, `number`, `slug`, `cefr`, `duration_min`, `title_en`, `title_ar`, `subtitle_en`, `subtitle_ar`, `pedagogical_overview_en`, `pedagogical_overview_ar`, `is_free_preview`) VALUES ('les-1-3', 'mod-1', '1.3', 'explaining-tasks', 'A2', 15, 'Explaining Tasks', 'شرح المهام والأنشطة التفاعلية', 'Modeling activities by demonstration rather than verbal monologue', 'نمذجة الأنشطة بالتطبيق العملي الملموس بدلاً من الشرح النظري الطويل', 'Showing is ten times more effective than telling. A 30-second teacher-student demonstration prevents 10 minutes of student paralysis. Never just say \"Do exercise 4\"; run through item 1 together as an open class demonstration.', 'التمثيل العملي أفضل بعشر مرات من الشرح النظري. عرض تجريبي مدته 30 ثانية مع أحد الطلاب يوفر 10 دقائق من الارتباك والأسئلة المتكررة. لا تقل فقط \"حلوا التمرين\"، بل حلوا النقطة الأولى سوياً كنموذج.', 0);
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-1-3', 'demonstrate', '/ˈdem.ən.streɪt/', 'يستعرض عملياً / ينمذج', 'Let me demonstrate with Omar first.', 'دعوني أستعرض التمرين مع عمر أولاً.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-1-3', 'model', '/ˈmɒd.əl/', 'يعطي نموذجاً مثالياً', 'Look at the model sentence on the board.', 'انظروا إلى الجملة النموذجية على السبورة.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-1-3', 'take turns', '/teɪk tɜːrnz/', 'يتبادل الأدوار', 'Take turns asking and answering.', 'تبادلوا الأدوار في طرح الأسئلة والإجابة.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-1-3', 'fill in the blanks', '/fɪl ɪn ðə blæŋks/', 'املاً الفراغات', 'Fill in the blanks with the correct preposition.', 'املأوا الفراغات بحرف الجر الصحيح.');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-1-3-1', 'les-1-3', 'Watch us first. Ahmed, ask me question one.', 'شاهدونا أولاً. يا أحمد، اسألني السؤال الأول.', '/wɒtʃ ʌs fɜːrst/', 'Task modeling initiating peer demonstration.', 'بدء النمذجة الحية مع طالب لتوضيح سير النشاط.', 'instruction');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-1-3-2', 'les-1-3', 'Student A is the interviewer; Student B is the job applicant. Switch after two minutes.', 'الطالب (أ) هو من يجري المقابلة، والطالب (ب) هو المتقدم للوظيفة. تبادلوا الأدوار بعد دقيقتين.', '/ˈstjuː.dənt eɪ ɪz ðə ˈɪn.tə.vjuː.ər/', 'Role-allocation formula eliminating role ambiguity.', 'توزيع محكم للأدوار يمنع الحيرة داخل المجموعات.', 'instruction');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-1-3-3', 'les-1-3', 'Let us do number 1 together as an example. Who knows the answer?', 'دعونا نحل النقطة رقم 1 سوياً كمثال. من يعرف الإجابة؟', '/let ʌs duː ˈnʌm.bər wʌn təˈɡeð.ər/', 'Scaffolded whole-class item trial before autonomous practice.', 'حل عينة تمهيدية بشكل جماعي قبل الإطلاق الفردي.', 'instruction');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-3', 1, 'Teacher', 'المعلم', 'Class, look at exercise 4. We will do an information gap activity.', 'يا طلاب، انظروا للتمرين 4. سنقوم بنشاط فجوة معلوماتية.');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-3', 2, 'Student', 'طالب', 'Teacher, what do we have to say?', 'أستاذ، ماذا علينا أن نقول؟');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-3', 3, 'Teacher', 'المعلم', 'Watch Mona and me. Mona, look at card A. Ask me about the train time.', 'شاهدوا منى وشاهدوني. يا منى، انظري لبطاقة A، واسأليني عن موعد القطار.');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-3', 4, 'Student', 'طالب', 'What time does the train leave for Alexandria?', 'في أي وقت يغادر القطار إلى الإسكندرية؟');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-3', 5, 'Teacher', 'المعلم', 'It leaves at 9:15 AM. You see? Now Student A asks, Student B answers. Switch afterwards. Go!', 'يغادر في الساعة 9:15 صباحاً. رأيتم؟ الآن (أ) يسأل و (ب) يجيب، ثم تبادلوا. ابدأوا!');
INSERT INTO `exercises` (`id`, `lesson_id`, `prompt_en`, `prompt_ar`, `context_en`, `context_ar`, `explanation_en`, `explanation_ar`, `source_reference`) VALUES ('ex-1-3-1', 'les-1-3', 'Before starting an information-gap speaking task, what is the best CELTA-aligned action?', 'قبل بدء نشاط محادثة ثنائي، ما هو الإجراء الأفضل الموصى به تربوياً؟', 'Students are confused about who talks first and what questions to ask.', 'الطلاب مترددون بشأن من يبدأ الحديث ونوع الأسئلة المطلوبة.', 'Live teacher-student demonstration creates immediate cognitive clarity without unnecessary L1 translation.', 'النمذجة الحية بين المعلم والطالب تصنع فهماً فورياً ومباشراً دون الحاجة للجوء إلى الترجمة الحرفية.', 'Adrian Underhill, Sound Foundations & Training Guidelines (Macmillan, 2005)');
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-1', 'ex-1-3-1', 'Read the written instructions from the textbook three times loudly.', 'قراءة التعليمات المكتوبة بصوت عالٍ 3 مرات.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-2', 'ex-1-3-1', 'Demonstrate one full question-and-answer exchange with a student in front of the whole class.', 'نمذجة سؤال وجواب كاملين مع طالب متطوع أمام الفصل بأكمله.', 1);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-3', 'ex-1-3-1', 'Translate the whole dialogue into Arabic so they understand.', 'ترجمة المحادثة كاملة للعربية.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-4', 'ex-1-3-1', 'Let them figure it out by trial and error.', 'تركهم يكتشفون ذلك بالتجربة والخطأ دون توجيه.', 0);
INSERT INTO `assignments` (`id`, `lesson_id`, `title_en`, `title_ar`, `instructions_en`, `instructions_ar`) VALUES ('asgn-les-1-3', 'les-1-3', 'Task Demonstration Plan', 'خطة نمذجة نشاط تفاعلي', 'Design a script for modeling a role-play activity (doctor and patient) with a volunteer student in 3 short dialogue turns.', 'صمم سيناريو لنمذجة نشاط تمثيل أدوار (طبيب ومريض) مع طالب متطوع في 3 تبادلات حوارية قصيرة.');
INSERT INTO `lessons` (`id`, `module_id`, `number`, `slug`, `cefr`, `duration_min`, `title_en`, `title_ar`, `subtitle_en`, `subtitle_ar`, `pedagogical_overview_en`, `pedagogical_overview_ar`, `is_free_preview`) VALUES ('les-1-4', 'mod-1', '1.4', 'checking-understanding', 'B1', 15, 'Checking Understanding', 'التأكد من الفهم وصياغة أسئلة ICQs', 'Banishing \"Do you understand?\" in favor of binary and factual ICQs', 'التخلص النهائي من سؤال \"هل فهمتم؟\" واستبداله بأسئلة التحقق المحددة', 'Students almost always answer \"Yes\" to \"Do you understand?\" out of embarrassment or social compliance. ICQs test comprehension objectively by asking factual questions about what they must do next.', 'الطلاب يجيبون دائماً بـ \"نعم\" لسؤال \"هل فهمتم؟\" بدافع الحرج الاجتماعي. أسئلة الـ ICQs تقيس الفهم الفعلي بطرح أسئلة محددة عن الخطوة الإجرائية التالية التي سيقومون بها.', 0);
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-1-4', 'comprehend', '/ˌkɒm.prɪˈhend/', 'يستوعب / يدرك', 'Make sure all students comprehend the task.', 'تأكد من أن جميع الطلاب يستوعبون المهمة.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-1-4', 'alone', '/əˈloʊn/', 'بمفرده / فردياً', 'Are you working alone or in pairs?', 'هل تعملون بمفردكم أم في أزواج؟');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-1-4', 'instruction', '/ɪnˈstrʌk.ʃən/', 'تعليمة / إرشاد', 'Check the instructions before writing.', 'تحقق من التعليمات قبل الكتابة.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-1-4', 'timeframe', '/ˈtaɪm.freɪm/', 'الإطار الزمني', 'What is our timeframe for this stage?', 'ما هو إطارنا الزمني لهذه المرحلة؟');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-1-4-1', 'les-1-4', 'Are you writing complete sentences, or just bullet points? Karim?', 'هل تكتبون جملاً كاملة أم مجرد نقاط موجزة؟ يا كريم؟', '/ɑːr juː ˈraɪ.tɪŋ kəmˈpliːt ˈsen.tən.sɪz/', 'Targeted ICQ preventing wrong output format.', 'سؤال تحقق إجرائي موجه لطالب محدد بالاسم لضبط مخرج النشاط.', 'questioning');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-1-4-2', 'les-1-4', 'How many minutes do you have? Sarah?', 'كم دقيقة لديكم لإنجاز هذا؟ يا سارة؟', '/haʊ ˈmen.i ˈmɪn.ɪts duː juː hæv/', 'Timeframe ICQ securing urgency.', 'سؤال تحقق للتأكيد على الوعي بالوقت والجدية.', 'questioning');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-1-4-3', 'les-1-4', 'Are you speaking in English, or Arabic? Exactly, English only!', 'هل تتحدثون بالإنجليزية أم بالعربية؟ بالضبط، الإنجليزية فقط!', '/ˈɪŋ.ɡlɪʃ ɔːr ˈær.ə.bɪk/', 'Language policy ICQ reinforcing Target Language immersion.', 'سؤال تحقق تربوي يجدد التذكير بسياسة استخدام اللغة الإنجليزية.', 'management');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-4', 1, 'Teacher', 'المعلم', 'In groups of three, brainstorm four causes of global warming. Three minutes.', 'في مجموعات ثلاثية، اذكروا أربعة أسباب للاحتباس الحراري. لديكم ثلاث دقائق.');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-4', 2, 'Teacher', 'المعلم', 'Ali, are you working alone or in groups?', 'يا علي، هل تعمل بمفردك أم في مجموعات؟');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-4', 3, 'Student', 'طالب', 'In groups of three, sir.', 'في مجموعات ثلاثية يا أستاذ.');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-4', 4, 'Teacher', 'المعلم', 'Mariam, are you writing full essays, or short points?', 'يا مريم، هل تكتبون مقالات كاملة أم نقاطاً موجزة؟');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-4', 5, 'Student', 'طالب', 'Short points only.', 'نقاطاً موجزة فقط.');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-4', 6, 'Teacher', 'المعلم', 'Superb! How many minutes do you have, Tarek? Three minutes. Begin!', 'ممتاز! كم دقيقة لديكم يا طارق؟ ثلاث دقائق. انطلقوا!');
INSERT INTO `exercises` (`id`, `lesson_id`, `prompt_en`, `prompt_ar`, `context_en`, `context_ar`, `explanation_en`, `explanation_ar`, `source_reference`) VALUES ('ex-1-4-1', 'les-1-4', 'Which of the following is a genuine ICQ (Instruction Checking Question)?', 'أي من الأسئلة التالية يُعد سؤال تحقق حقيقي من فهم التعليمات (ICQ)؟', 'You instructed students to interview 2 classmates for 5 minutes without writing.', 'وجهت الطلاب لإجراء مقابلة مع زميلين لمدة 5 دقائق دون استخدام الكتابة.', '\"Are you writing or just listening?\" checks the exact physical behavior expected, whereas \"Do you understand?\" yields empty yeses.', 'سؤال \"هل تكتبون أم تستمعون فقط؟\" يفحص السلوك المطلوب بدقة، بينما سؤال \"هل فهمتم؟\" يستدعي إجابات نعم شكلية.', 'Cambridge English Assessment, CELTA Trainer Guidelines');
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-1', 'ex-1-4-1', 'Do you understand what you need to do?', 'هل فهمتم ما يجب عليكم فعله؟', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-2', 'ex-1-4-1', 'Is everything crystal clear to everyone?', 'هل كل شيء واضح تماماً للجميع؟', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-3', 'ex-1-4-1', 'Are you writing down their answers, or just listening? Hany?', 'هل تكتبون إجاباتهم، أم تستمعون فقط؟ يا هاني؟', 1);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-4', 'ex-1-4-1', 'Who likes this exercise?', 'من يحب هذا التمرين؟', 0);
INSERT INTO `assignments` (`id`, `lesson_id`, `title_en`, `title_ar`, `instructions_en`, `instructions_ar`) VALUES ('asgn-les-1-4', 'les-1-4', 'Drafting 3 Targeted ICQs', 'صياغة 3 أسئلة تحقق دقيقة (ICQs)', 'Given this task: \"Students work in pairs to reorder 5 sentences without looking at page 10.\" Write 3 snappy ICQs to check understanding.', 'بناءً على هذا النشاط: \"يعمل الطلاب في أزواج لإعادة ترتيب 5 جمل دون النظر لصفحة 10.\" اكتب 3 أسئلة ICQ دقيقة للتأكد من الفهم.');
INSERT INTO `lessons` (`id`, `module_id`, `number`, `slug`, `cefr`, `duration_min`, `title_en`, `title_ar`, `subtitle_en`, `subtitle_ar`, `pedagogical_overview_en`, `pedagogical_overview_ar`, `is_free_preview`) VALUES ('les-1-5', 'mod-1', '1.5', 'ending-lesson', 'A2', 15, 'Ending the Lesson & Homework', 'إنهاء الحصة وتكليف الواجبات المنزلية', 'Orderly lesson closure, clear homework deadlines, and positive farewells', 'الختام المنظم للحصة، تحديد مواعيد الواجبات بدقة، والوداع المحفز للطلاب', 'Rushing homework instructions while students pack their bags is a primary cause of non-completion. Allocate the final 4 minutes to summarize key learning gains, write homework cleanly on the board, and dismiss row by row.', 'الاستعجال في إملاء الواجب أثناء جمع الطلاب لأدواتهم هو السبب الأول لعدم حل الواجب. خصص آخر 4 دقائق لتلخيص مكاسب الحصة، وتدوين الواجب بوضوح على السبورة، وصرف الطلاب بهدوء.', 0);
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-1-5', 'pack away', '/pæk əˈweɪ/', 'يجمع أدواته وحقيبته', 'Please pack away your books quietly.', 'رجاءً اجمعوا كتبكم وأدواتكم بهدوء.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-1-5', 'assignment', '/əˈsaɪn.mənt/', 'واجب / تكليف', 'Your written assignment is due on Sunday.', 'موعد تسليم واجبكم الكتابي هو يوم الأحد.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-1-5', 'due date', '/ˈdjuː ˌdeɪt/', 'موعد التسليم النهائي', 'Remember, the due date is strictly tomorrow morning.', 'تذكروا، موعد التسليم النهائي صباح الغد تحديداً.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-1-5', 'dismissed', '/dɪsˈmɪst/', 'مسموح لكم بالانصراف', 'Row 1, you are dismissed. Have a great day!', 'الصف الأول، يمكنكم الانصراف. أتمنى لكم يوماً رائعاً!');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-1-5-1', 'les-1-5', 'Pens down, close your notebooks, and look at the board.', 'ضعوا الأقلام، أغلقوا دفاتركم، وانظروا إلى السبورة.', '/penz daʊn, kloʊz jɔːr ˈnoʊt.bʊks/', 'Terminal cue transitioning from active work to closure.', 'إشارة ختامية تنقل الطلاب من العمل الفردي إلى مرحلة إغلاق الحصة.', 'management');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-1-5-2', 'les-1-5', 'For homework: page 35, exercises 2 and 3. Due next Tuesday morning.', 'بالنسبة للواجب المنزلي: صفحة 35، التمرينان 2 و 3. التسليم صباح الثلاثاء القادم.', '/fɔːr ˈhoʊm.wɜːrk peɪdʒ θɜːr.ti faɪv/', 'Explicit homework briefing with precise location and deadline.', 'تكليف محدد بالصفحة ورقم التمرين وتاريخ التسليم الدقيق.', 'instruction');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-1-5-3', 'les-1-5', 'Row by row. When your area is tidy, you may leave. Have a wonderful weekend!', 'صفاً تلو الآخر. عندما يكون مكانكم نظيفاً ومرتباً، يمكنكم الانصراف. عطلة نهاية أسبوع رائعة!', '/roʊ baɪ roʊ/', 'Structured orderly exit ritual.', 'بروتوكول انصراف منظم يحافظ على هيبة الفصل والنظام المدرسي.', 'management');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-5', 1, 'Teacher', 'المعلم', 'Time is up! Stop writing, please. Look up here.', 'انتهى الوقت! توقفوا عن الكتابة من فضلكم. انظروا هنا.');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-5', 2, 'Class', 'الفصل', '(The bell rings in the hallway)', '(يدق الجرس في الممر)');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-5', 3, 'Teacher', 'المعلم', 'The bell has rung, but the lesson ends when I dismiss you. Thank you. Homework is on the board: page 45, write 5 sentences. Write it in your agenda now.', 'دق الجرس، لكن الحصة تنتهي حين أصرفكم أنا. شكراً لكم. الواجب مدون على السبورة: صفحة 45، اكتبوا 5 جمل. سجلوها في مفكرتكم الآن.');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-5', 4, 'Student', 'طالب', 'Can we send it on Google Classroom, sir?', 'هل يمكننا إرساله عبر جوجل كلاسروم يا أستاذ؟');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-1-5', 5, 'Teacher', 'المعلم', 'Yes, by 8 PM tomorrow. Window row may leave first. Good afternoon everyone!', 'نعم، بحلول الثامنة مساء الغد. صف النافذة يمكنكم الانصراف أولاً. طاب يومكم جميعاً!');
INSERT INTO `exercises` (`id`, `lesson_id`, `prompt_en`, `prompt_ar`, `context_en`, `context_ar`, `explanation_en`, `explanation_ar`, `source_reference`) VALUES ('ex-1-5-1', 'les-1-5', 'What is the most professional procedure when the bell rings while you are concluding a lesson?', 'ما هو الإجراء الأكثر مهنية عند رنين الجرس وأنت في مرحلة ختام الحصة؟', 'Students start putting their bags on their shoulders and walking out.', 'بدأ الطلاب في حمل حقائبهم والتوجه نحو الباب فور سماع الجرس.', 'Maintaining authority and predictable routines ensures safety, respect, and clear homework comprehension.', 'الحفاظ على الروتين والهدوء يضمن احترام الحرم الصفي وفهم الطلاب الكامل لما هو مطلوب منهم في المنزل.', 'Jim Scrivener, Classroom Management Techniques (Cambridge, 2012)');
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-1', 'ex-1-5-1', 'Shout homework details louder over their chatter.', 'الصراخ بتفاصيل الواجب بصوت أعلى فوق أصواتهم.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-2', 'ex-1-5-1', 'Calmly remind them that the bell informs the teacher, but the teacher dismisses the class, and deliver closure.', 'تذكيرهم بهدوء بأن الجرس ينبه المعلم، لكن المعلم هو من يصرف الفصل، وإتمام الختام بنظام.', 1);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-3', 'ex-1-5-1', 'Cancel homework completely.', 'إلغاء الواجب المنزلي نهائياً.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-4', 'ex-1-5-1', 'Lock the classroom door and punish everyone.', 'إغلاق الباب بالمفتاح ومعاقبة الجميع.', 0);
INSERT INTO `assignments` (`id`, `lesson_id`, `title_en`, `title_ar`, `instructions_en`, `instructions_ar`) VALUES ('asgn-les-1-5', 'les-1-5', 'End-of-Lesson Closure Plan', 'خطة إغلاق الحصة والصرف المنظم', 'Write a step-by-step 3-minute closing protocol for your classroom, including homework announcement, board clearing, and dismissal order.', 'اكتب بروتوكولاً لآخر 3 دقائق من حصتك يتضمن إعلان الواجب، وتنظيف السبورة، وآلية صرف الطلاب بنظام.');
INSERT INTO `curriculum_modules` (`id`, `number`, `title_en`, `title_ar`, `cefr_range`, `color`, `description_en`, `description_ar`) VALUES ('mod-2', 2, 'Explaining Lessons & Checking Student Understanding', 'شرح الدروس والتحقق من فهم واستيعاب الطلاب', 'B1–B2', '#0284C7', 'Develop crystal-clear concept explanation strategies, analogy building, Concept Checking Questions (CCQs), diagnostic re-explaining, and student-centered questioning techniques.', 'تطوير استراتيجيات تقديم المفاهيم بوضوح تام، وبناء القياس والتشبيه، وصياغة أسئلة فحص المفاهيم (CCQs)، وإعادة الشرح التشخيصي، وتقنيات إثارة التفكير والمشاركة.');
INSERT INTO `lessons` (`id`, `module_id`, `number`, `slug`, `cefr`, `duration_min`, `title_en`, `title_ar`, `subtitle_en`, `subtitle_ar`, `pedagogical_overview_en`, `pedagogical_overview_ar`, `is_free_preview`) VALUES ('les-2-1', 'mod-2', '2.1', 'introducing-concepts', 'B1', 20, 'Introducing New Concepts', 'تقديم المفاهيم الجديدة وبناء السياق', 'The inductive discovery method: elicitation and context building over lecture', 'طريقة الاستقراء والاكتشاف: استدراج الأفكار وبناء السياق بدلاً من التلقين', 'Inductive teaching (guided discovery) leads to vastly superior long-term retention compared to deductive lecturing. Rather than writing a grammar rule on the board, effective teachers present a story, elicit what is happening, and guide students to notice patterns.', 'التدريس الاستقرائي (الاكتشاف الموجه) يحقق رسوخاً معرفياً يفوق بمراحل التلقين المباشر. بدلاً من سرد القواعد الجافة على السبورة، يقدم المعلم قصة أو موقفاً، ويستدرج استنتاج القاعدة من الطلاب أنفسهم.', 0);
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-2-1', 'elicit', '/iˈlɪs.ɪt/', 'يستدرج / يستخرج الإجابة من الطالب', 'Try to elicit the rule from the students first.', 'حاول استدراج القاعدة من الطلاب أولاً.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-2-1', 'context', '/ˈkɒn.tekst/', 'السياق التواصلي أو الموقفي', 'Always present new vocabulary in a clear context.', 'قدّم دائماً المفردات الجديدة داخل سياق واضح.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-2-1', 'concept', '/ˈkɒn.sept/', 'مفهوم لغوي أو معرفي', 'Today we explore the concept of ongoing past actions.', 'اليوم نستكشف مفهوم الأفعال المستمرة في الماضي.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-2-1', 'discovery', '/dɪˈskʌv.ər.i/', 'اكتشاف موجه', 'Guided discovery makes learning memorable.', 'الاكتشاف الموجه يجعل التعلم غير قابل للنسيان.');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-2-1-1', 'les-2-1', 'Look at this picture. What do you think happened to this man right before this?', 'انظروا إلى هذه الصورة. ماذا تعتقدون أنه حدث لهذا الرجل قبل هذه اللحظة مباشرة؟', '/lʊk æt ðɪs ˈpɪk.tʃər/', 'Visual prompt eliciting target past perfect tense.', 'محفز بصري يستدرج استنتاج صيغة الماضي التام بشكل طبيعي.', 'questioning');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-2-1-2', 'les-2-1', 'Notice the underlined words in these three sentences. What do they have in common?', 'لاحظوا الكلمات التي تحتها خط في هذه الجمل الثلاث. ما الشيء المشترك بينها؟', '/ˈnoʊ.tɪs ðə ˌʌn.dərˈlaɪnd wɜːrdz/', 'Guided discovery prompt directing cognitive pattern-matching.', 'سؤال اكتشاف موجه يثير التفكير المقارن واستنتاج القواسم المشتركة.', 'instruction');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-2-1-3', 'les-2-1', 'Imagine you have an important plane to catch tomorrow morning. What will you say?', 'تخيلوا أن لديكم رحلة طيران مهمة صباح الغد. ماذا ستقولون؟', '/ɪˈmædʒ.ɪn juː hæv/', 'Real-world hypothetical scenario setting communicative need.', 'بناء سيناريو واقعي يشعر الطالب بالحاجة الحقيقية للتعبير اللغوي.', 'instruction');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-1', 1, 'Teacher', 'المعلم', 'Look at the photo on the projector. This is Dave. His shoes are muddy and he is exhausted. Why?', 'انظروا للصورة على جهاز العرض. هذا ديف. حذاؤه ملطخ بالطين وهو منهك تماماً. لماذا؟');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-1', 2, 'Student A', 'طالب أ', 'Because he was running in the rain!', 'لأنه كان يركض تحت المطر!');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-1', 3, 'Teacher', 'المعلم', 'Brilliant! \"Dave has been running in the rain.\" Is he running right now at this second?', 'رائع! \"كان ديف يركض تحت المطر\". هل يركض الآن في هذه اللحظة؟');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-1', 4, 'Class', 'الفصل', 'No! He stopped.', 'كلا! لقد توقف.');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-1', 5, 'Teacher', 'المعلم', 'Exactly. But can we see the result now? Yes, his muddy shoes. This is the Present Perfect Continuous.', 'بالضبط. لكن هل نرى النتيجة واضحة الآن؟ نعم، حذاؤه الملطخ. هذا هو المضارع التام المستمر.');
INSERT INTO `exercises` (`id`, `lesson_id`, `prompt_en`, `prompt_ar`, `context_en`, `context_ar`, `explanation_en`, `explanation_ar`, `source_reference`) VALUES ('ex-2-1-1', 'les-2-1', 'In communicative language teaching (CLT), what should a teacher establish FIRST when presenting a new grammatical structure?', 'في التدريس التواصلي المعاصر (CLT)، ما الذي يجب على المعلم ترسيخه أولاً عند تقديم تركيب قواعدي جديد؟', 'You want to introduce the conditional \"If I were you, I would...\".', 'تريد تقديم قاعدة النصيحة التخيلية \"لو كنت مكانك...\".', 'Meaning (M) must precede Form (F) and Pronunciation (P). Context gives purpose to grammar.', 'ترسيخ المعنى التواصلي والسياقي يسبق دائماً استعراض تفاصيل القواعد والشكل المجرد.', 'Jeremy Harmer, How to Teach English (Pearson Longman)');
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-1', 'ex-2-1-1', 'The phonetic spelling and IPA symbols of the words.', 'الرموز الصوتية للكلمات.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-2', 'ex-2-1-1', 'The communicative meaning and context in which native speakers use it.', 'المعنى التواصلي والسياق الواقعي الذي يستخدم فيه المتحدثون الأصليون هذه الصيغة.', 1);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-3', 'ex-2-1-1', 'The list of irregular grammatical exceptions.', 'قائمة الاستثناءات الشاذة للقاعدة.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-4', 'ex-2-1-1', 'The translation into Arabic grammar terminology.', 'المصطلحات النحوية باللغة العربية.', 0);
INSERT INTO `assignments` (`id`, `lesson_id`, `title_en`, `title_ar`, `instructions_en`, `instructions_ar`) VALUES ('asgn-les-2-1', 'les-2-1', 'Context-Building Lesson Starter', 'خطة تمهيد وبناء سياق لمفهوم لغوي', 'Write a 100-word introduction establishing a context to elicit the past continuous (\"was walking when...\") without explicitly naming the tense initially.', 'اكتب نص تمهيد من 100 كلمة يبني سياقاً لاستدراج الماضي المستمر دون ذكر اسم القاعدة في البداية.');
INSERT INTO `lessons` (`id`, `module_id`, `number`, `slug`, `cefr`, `duration_min`, `title_en`, `title_ar`, `subtitle_en`, `subtitle_ar`, `pedagogical_overview_en`, `pedagogical_overview_ar`, `is_free_preview`) VALUES ('les-2-2', 'mod-2', '2.2', 'using-examples', 'B1', 15, 'Using Examples & Analogies', 'استخدام الأمثلة الحسية والتشبيهات التوضيحية', 'Crafting memorable contrasts, timelines, and realia to clarify abstract concepts', 'صناعة المقارنات الذهنية والخطوط الزمنية واستخدام المجسمات لتجسيد المفاهيم المجردة', 'Abstract grammatical terminology fails when teaching teenagers and younger learners. Visual timelines, physical gestures, and relatable comparisons anchor difficult concepts into concrete mental imagery.', 'المصطلحات النحوية المجردة تفشل مع الطلاب في سن المراهقة والشباب. الخطوط الزمنية والتشبيهات الحركية تحول المفاهيم الصعبة إلى صور ذهنية ملموسة لا تنسى.', 0);
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-2-2', 'analogy', '/əˈnæl.ə.dʒi/', 'قياس أو تشبيه توضيحي', 'Think of an analogy comparing memory to a computer folder.', 'فكر في تشبيه يقارن الذاكرة بمجلدات الحاسوب.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-2-2', 'timeline', '/ˈtaɪm.laɪn/', 'خط زمني مرئي للأزمنة', 'Draw a timeline on the board to show past versus present.', 'ارسم خطاً زمنياً على السبورة لتوضيح الماضي مقارنة بالحاضر.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-2-2', 'contrast', '/ˈkɒn.trɑːst/', 'مقارنة تباينية', 'Contrast \"used to do\" with \"is used to doing\".', 'قارن بشكل تبايني بين الصيغتين.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-2-2', 'concrete', '/ˈkɒŋ.kriːt/', 'ملموس / حسي', 'Give concrete examples from daily school life.', 'قدم أمثلة ملموسة من واقع الحياة المدرسية اليومية.');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-2-2-1', 'les-2-2', 'Think of \"must\" like a traffic light turning red: you have no choice.', 'فكروا في كلمة \"must\" مثل إشارة المرور الحمراء: ليس لديكم خيار آخر.', '/θɪŋk ɒv mʌst laɪk/', 'Concrete rule of life analogy simplifying modal obligation.', 'تشبيه ملموس من قوانين الحياة يرسخ مفهوم الإلزام الصارم.', 'instruction');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-2-2-2', 'les-2-2', 'Look at the timeline. Here is NOW. The action started here, and touches right now.', 'انظروا للخط الزمني. هذه هي نقطة \"الآن\". بدأ الفعل هنا، ويصل أثره للحظة الحالية.', '/lʊk æt ðə ˈtaɪm.laɪn/', 'Deictic anchoring of present perfect aspect.', 'تثبيت بصري على الخط الزمني يجسد العلاقة بين الماضي والحاضر.', 'instruction');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-2-2-3', 'les-2-2', 'Compare these two sentences: \"I stopped to smoke\" versus \"I stopped smoking\". What is the difference?', 'قارنوا بين هاتين الجملتين: \"I stopped to smoke\" مقابل \"I stopped smoking\". ما الفرق؟', '/kəmˈpeər ðiːz tuː ˈsen.tən.sɪz/', 'Minimal pair contrast revealing semantic shifts with gerunds/infinitives.', 'مقارنة لغوية تباينية دقيقة تكشف تغير المعنى بين المصدر واسم الفاعل.', 'questioning');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-2', 1, 'Teacher', 'المعلم', 'Class, look at the timeline on the board. Here is 2020, and here is 2026. What does \"I have lived in Cairo for six years\" mean?', 'يا طلاب، انظروا للخط الزمني على السبورة. هنا عام 2020، وهنا 2026. ماذا تعني هذه الجملة؟');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-2', 2, 'Student', 'طالب', 'It means you lived in Cairo before, but now you moved?', 'تعني أنك عشت في القاهرة سابقاً، لكنك انتقلت الآن؟');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-2', 3, 'Teacher', 'المعلم', 'Watch my finger on the timeline! Does the line stop at 2026, or continue?', 'راقبوا إصبعي على الخط الزمني! هل توقف الخط عند 2026 أم يمتد للمستقبل؟');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-2', 4, 'Student', 'طالب', 'It continues! You still live in Cairo now!', 'إنه يمتد! أنت ما زلت تعيش في القاهرة الآن!');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-2', 5, 'Teacher', 'المعلم', 'Spot on! That is the bridge of the Present Perfect.', 'أصبت كبد الحقيقة! هذا هو الجسر الزمني للمضارع التام.');
INSERT INTO `exercises` (`id`, `lesson_id`, `prompt_en`, `prompt_ar`, `context_en`, `context_ar`, `explanation_en`, `explanation_ar`, `source_reference`) VALUES ('ex-2-2-1', 'les-2-2', 'Which visual representation best clarifies the distinction between Past Simple and Present Perfect?', 'أي وسيلة توضيح بصرية هي الأفضل لبيان الفرق بين الماضي البسيط والمضارع التام؟', 'Students keep using Past Simple for unfinished actions extending to the present.', 'الطلاب يخلطون بين الأحداث المنتهية والأحداث التي لا يزال لها امتداد حاضر.', 'Timelines provide spatial representation of temporal concepts, overcoming L1 interference.', 'الخطوط الزمنية تعطي تمثيلاً مكانياً واضحاً للمفاهيم الزمنية، مما يمنع التداخل اللغوي السلبي.', 'Jim Scrivener, Teaching English Grammar (Macmillan)');
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-1', 'ex-2-2-1', 'A list of 50 irregular verbs in alphabetical order.', 'قائمة بخمسين فعلاً شاذاً مرتبة أبجدياً.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-2', 'ex-2-2-1', 'A timeline contrasting a closed past box (finished time) with an arrow reaching the NOW line (unfinished time).', 'خط زمني يقارن بين صندوق ماضٍ مغلق وسهم متصل يصل إلى خط \"الآن\".', 1);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-3', 'ex-2-2-1', 'A dictionary definition of the word \"perfect\".', 'التعريف المعجمي لكلمة تام.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-4', 'ex-2-2-1', 'Translating both sentences identically into Arabic.', 'ترجمة كلتا الجملتين بنفس الطريقة للعربية.', 0);
INSERT INTO `assignments` (`id`, `lesson_id`, `title_en`, `title_ar`, `instructions_en`, `instructions_ar`) VALUES ('asgn-les-2-2', 'les-2-2', 'Visual Board Timeline Design', 'تصميم خط زمني تعليمي للسبورة', 'Sketch or describe in writing a board diagram explaining the difference between \"I was reading\" and \"I had read\".', 'ارسم أو صف كتابةً رسماً بيانياً للسبورة يوضح الفرق الدقيق بين الماضي المستمر والماضي التام.');
INSERT INTO `lessons` (`id`, `module_id`, `number`, `slug`, `cefr`, `duration_min`, `title_en`, `title_ar`, `subtitle_en`, `subtitle_ar`, `pedagogical_overview_en`, `pedagogical_overview_ar`, `is_free_preview`) VALUES ('les-2-3', 'mod-2', '2.3', 'student-questions', 'B2', 20, 'Handling Student Questions', 'إدارة وتوجيه أسئلة واستفسارات الطلاب', 'Bouncing questions back, handling unexpected vocabulary, and pacing the lesson', 'إعادة تدوير الأسئلة بين الأقران، التعامل مع الكلمات المباغتة، وحماية وقت الحصة', 'When a teacher answers every student question immediately, the class becomes teacher-dependent. Expert practitioners use \"bouncing\": they redirect the question to peers, validate curiosity, and defer tangential topics to the \"Parking Lot\" on the board.', 'حين يتولى المعلم الإجابة الفورية عن كل استفسار، يتحول الفصل إلى بيئة اتكالية. المعلم المحترف يعيد توجيه السؤال للزملاء، ويقدر الفضول المعرفي، ويدرج الأسئلة الجانبية في ركن الملاحظات المؤجلة (Parking Lot).', 0);
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-2-3', 'bounce back', '/baʊns bæk/', 'يعيد طرح السؤال على الفصل', 'Bounce the question back to see if anyone else knows.', 'أعد طرح السؤال على الزملاء لترى إن كان أحدهم يعرف الإجابة.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-2-3', 'parking lot', '/ˈpɑːr.kɪŋ ˌlɒt/', 'ركن الأسئلة المؤجلة على السبورة', 'Let us put that question in our board parking lot.', 'دعونا نضع ذلك السؤال في ركن الأسئلة المؤجلة على السبورة.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-2-3', 'tangent', '/ˈtæn.dʒənt/', 'مسار جانبي بعيد عن الهدف', 'Do not go off on a tangent during grammar practice.', 'لا تنجرف في مسار جانبي أثناء تدريب القواعد.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-2-3', 'credible', '/ˈkred.ə.bəl/', 'موثوق وذو مصداقية', 'It is credible and honest to verify a rare idiom.', 'من تمام المصداقية والأمانة العلمية التحقق من التعبيرات النادرة.');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-2-3-1', 'les-2-3', 'That is a fantastic question, Youssef! Who in the room can help Youssef with that?', 'هذا سؤال رائع يا يوسف! من في الفصل يستطيع مساعدة يوسف في هذه النقطة؟', '/ðæt ɪz ə fænˈtæs.tɪk ˈkwes.tʃən/', 'Peer redirection building collaborative classroom culture.', 'إعادة توجيه ذكية تعزز روح البحث والتفكير الجماعي بين الطلاب.', 'questioning');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-2-3-2', 'les-2-3', 'I love your curiosity, but let us park that on the corner of the board and discuss it at break.', 'أحيي فيك هذا الشغف، ولكن دعنا نضع هذا السؤال في جانب السبورة ونناقشه في الاستراحة.', '/let ʌs pɑːrk ðæt ɒn ðə ˈkɔːr.nər/', 'Polite boundary-setting protecting lesson pacing.', 'حفظ مهذب لوقت الحصة يمنع التشتت دون كسر عزيمة الطالب.', 'management');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-2-3-3', 'les-2-3', 'That is a rare nuance. Let me double-check the exact dictionary collocation and get back to you tomorrow.', 'هذا استخدام بلاغي دقيق ونادر. دعني أتحقق من التلازم اللفظي الدقيق في المعجم وأجيبك غداً.', '/let miː ˈdʌb.əl tʃek/', 'Professional honesty modeling academic humility.', 'أمانة علمية ومهنية تعكس التواضع الأكاديمي وتعزز ثقة الطلاب في المعلم.', 'feedback');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-3', 1, 'Student', 'طالب', 'Teacher, what is the difference between \"affect\" with an A and \"effect\" with an E?', 'أستاذ، ما الفرق بين affect بحرف A و effect بحرف E؟');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-3', 2, 'Teacher', 'المعلم', 'Great question, Nour! Before I answer, who can tell us which one is usually the action verb?', 'سؤال رائع يا نور! قبل أن أجيب، من يخبرنا أي منهما يأتي كفعل عادة؟');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-3', 3, 'Student B', 'طالب ب', '\"Affect\" with an A is the verb!', 'التي تبدأ بحرف A هي الفعل!');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-3', 4, 'Teacher', 'المعلم', 'Exactly! A for Action, A for Affect. Look at how well you worked that out together!', 'بالضبط! حرف A يرمز للـ Action ويرمز لـ Affect. انظروا كم كان رائعاً استنتاجكم للأمر معاً!');
INSERT INTO `exercises` (`id`, `lesson_id`, `prompt_en`, `prompt_ar`, `context_en`, `context_ar`, `explanation_en`, `explanation_ar`, `source_reference`) VALUES ('ex-2-3-1', 'les-2-3', 'A student asks a complex, off-topic grammatical question during a timed reading warm-up. What is the best teacher response?', 'سأل طالب سؤالاً نحوياً عميقاً لكنه خارج موضوع الحصة أثناء نشاط تهيئة قراءة محدد بوقت. ما هو التصرف الأمثل؟', 'The class only has 35 minutes left to complete the core syllabus objectives.', 'متبقي 35 دقيقة فقط في الحصة لإنهاء أهداف المنهج الأساسية.', 'The parking lot strategy honors curiosity while safeguarding instructional time and lesson objectives.', 'استراتيجية الأسئلة المؤجلة تقدر فضول الطالب وتحفظ في الوقت نفسه الخطة الزمنية للحصة.', 'Jeremy Harmer, The Practice of English Language Teaching');
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-1', 'ex-2-3-1', 'Ignore the student completely and pretend you did not hear.', 'تجاهل الطالب تماماً والادعاء بعدم سماع السؤال.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-2', 'ex-2-3-1', 'Acknowledge the quality of the question, place it on the board \"Parking Lot\", and promise to answer during the wrap-up or break.', 'الإشادة بعمق السؤال، وتدوينه في خانة الأسئلة المؤجلة على السبورة، والتعهد بمناقشته في ختام الحصة أو الاستراحة.', 1);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-3', 'ex-2-3-1', 'Spend 20 minutes explaining all related grammar rules right now.', 'قضاء 20 دقيقة في شرح كل القواعد المتعلقة الآن.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-4', 'ex-2-3-1', 'Reprimand the student for asking questions.', 'توبيخ الطالب على طرح الأسئلة.', 0);
INSERT INTO `assignments` (`id`, `lesson_id`, `title_en`, `title_ar`, `instructions_en`, `instructions_ar`) VALUES ('asgn-les-2-3', 'les-2-3', 'Question Redirection Simulation', 'محاكاة إعادة تدوير الأسئلة الطلابية', 'Write down two natural expressions you will say when a student asks: \"Teacher, why do we say interested IN but good AT?\"', 'اكتب عبارتين طبيعيتين لرد السؤال للفصل حين يسأل طالب: \"لماذا نقول interested in بينما نقول good at؟\"');
INSERT INTO `lessons` (`id`, `module_id`, `number`, `slug`, `cefr`, `duration_min`, `title_en`, `title_ar`, `subtitle_en`, `subtitle_ar`, `pedagogical_overview_en`, `pedagogical_overview_ar`, `is_free_preview`) VALUES ('les-2-4', 'mod-2', '2.4', 'reexplaining-lesson', 'B2', 20, 'Re-explaining Clearly', 'إعادة الشرح بوضوح وتبسيط المفاهيم', 'Diagnosing the breakdown, breaking syntax into micro-steps, and avoiding simply repeating louder', 'تشخيص مكمن الخلل، تفكيك التراكيب لخطوات دقيقة، وتجنب تكرار نفس الشرح بصوت أعلى', 'When learners do not understand, repeating the original explanation louder only increases anxiety. Effective educators diagnose the breakdown: they strip away non-essential words, utilize a different analogy, or draw a contrasting diagram.', 'حين يعجز الطلاب عن الاستيعاب، فإن تكرار نفس الشرح بصوت أعلى يضاعف من توترهم. المعلم القدير يشخص سبب التعثر: يتخلص من الحشو اللفظي، أو يستخدم تشبيهاً مختلفاً، أو يرسم رسماً بيانياً مقابلاً.', 0);
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-2-4', 'breakdown', '/ˈbreɪk.daʊn/', 'تعثر أو خلل في الفهم', 'Diagnose where the comprehension breakdown happened.', 'شخص أين حدث الخلل في الاستيعاب.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-2-4', 'rephrase', '/riːˈfreɪz/', 'يعيد الصياغة بأسلوب مبسط', 'Let me rephrase that using a simpler example.', 'دعني أعيد صياغة ذلك باستخدام مثال أكثر بساطة.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-2-4', 'scaffold', '/ˈskæf.əld/', 'يدعم تعليمياً بخطوات متدرجة', 'Scaffold the sentence with sentence frames on the board.', 'ادعم صياغة الجملة بنماذج هيكلية على السبورة.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-2-4', 'micro-step', '/ˈmaɪ.krəʊ step/', 'خطوة تدريجية مصغرة', 'Break this complex passive rule into three micro-steps.', 'قسم قاعدة المبني للمجهول إلى ثلاث خطوات مصغرة.');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-2-4-1', 'les-2-4', 'Let us take a step back and look at this from a fresh angle.', 'دعونا نتراجع خطوة للوراء وننظر للأمر من زاوية جديدة تماماً.', '/let ʌs teɪk ə step bæk/', 'Anxiety-reducing transition signaling a fresh start.', 'عبارة تزيل الحرج والتوتر وتعلن عن انطلاقة تفسيرية جديدة.', 'transition');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-2-4-2', 'les-2-4', 'Forget the grammar labels for a minute. Look at this real situation instead.', 'انسوا المسميات النحوية الجافة لدقيقة. انظروا لهذا الموقف الحقيقي بدلاً من ذلك.', '/fərˈɡet ðə ˈɡræm.ər ˈleɪ.bəlz/', 'De-escalating cognitive overload caused by meta-language.', 'تخفيف العبء الذهني الناتج عن المصطلحات النحوية المعقدة.', 'instruction');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-2-4-3', 'les-2-4', 'Omar, if you bought a car yesterday, is it in your garage now? Yes. That is completed past.', 'يا عمر، لو اشتريت سيارة أمس، هل هي في مرآبك الآن؟ نعم. هذا هو الماضي المكتمل المنتهي.', '/ˈoʊ.mɑːr ɪf juː bɔːt ə kɑːr/', 'Socratic binary CCQ establishing tense finality.', 'سؤال سقراطي ثنائي ملموس يثبت اكتمال الحدث وانقطاعه عن الحاضر.', 'questioning');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-4', 1, 'Student', 'طالب', 'Teacher, I still do not get why we say \"If I had known, I would have gone\". It is so long!', 'أستاذ، ما زلت لا أفهم لماذا نقول \"If I had known, I would have gone\". الجملة طويلة ومعقدة جداً!');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-4', 2, 'Teacher', 'المعلم', 'No worries at all, Kareem. Let us reset. Did you know about the party yesterday?', 'لا تقلق أبداً يا كريم. دعنا نبدأ من جديد. هل كنت تعلم بوجود الحفلة أمس؟');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-4', 3, 'Student', 'طالب', 'No, nobody told me.', 'كلا، لم يخبرني أحد.');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-4', 4, 'Teacher', 'المعلم', 'Did you go to the party?', 'وهل ذهبت إلى الحفلة؟');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-4', 5, 'Student', 'طالب', 'No, I stayed home.', 'كلا، بقيت في المنزل.');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-4', 6, 'Teacher', 'المعلم', 'Exactly! Both are in the past, and both are imaginary. We use this structure to express regret about past things that did not happen. Much clearer?', 'بالضبط! كلا الأمرين حدثا في الماضي، وكلاهما تخيلي الآن. نستخدم هذا التركيب للتعبير عن الندم على شيء مضى. هل أصبحت أوضح الآن؟');
INSERT INTO `exercises` (`id`, `lesson_id`, `prompt_en`, `prompt_ar`, `context_en`, `context_ar`, `explanation_en`, `explanation_ar`, `source_reference`) VALUES ('ex-2-4-1', 'les-2-4', 'You want to check if students understand the sentence: \"She used to play tennis.\" Which CCQ sequence is correct?', 'تريد التأكد من استيعاب الطلاب لجملة: \"She used to play tennis\". أي تسلسل لأسئلة CCQs هو الصحيح؟', 'Checking the communicative aspect of \"used to + infinitive\".', 'التحقق من الدلالة الوظيفية لصيغة used to.', 'Effective CCQs dissect meaning into binary components (past habit vs. present cessation) without using the target phrase.', 'أسئلة CCQs الناجحة تفكك المعنى إلى عناصر ثنائية قطعية (عادة ماضية مقابل انقطاعها الآن) دون تكرار الكلمة نفسها.', 'Workman, Concept Questions and Time Lines (Chadburn Publishing)');
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-1', 'ex-2-4-1', 'Do you know how to use \"used to\"?', 'هل تعرفون كيف تستخدمون used to؟', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-2', 'ex-2-4-1', '1. Did she play tennis in the past? (Yes) 2. Did she play once or many times? (Many times/habit) 3. Does she play tennis now? (No).', '1. هل لعبت التنس في الماضي؟ (نعم) 2. هل لعبت مرة واحدة أم مرات عديدة؟ (مرات عديدة) 3. هل تلعب التنس الآن؟ (كلا).', 1);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-3', 'ex-2-4-1', 'Can anyone conjugate tennis in the present?', 'هل يستطيع أحد تصريف كلمة تنس في المضارع؟', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-4', 'ex-2-4-1', 'What is the grammatical part of speech of used?', 'ما هو الموقع الإعرابي لكلمة used؟', 0);
INSERT INTO `assignments` (`id`, `lesson_id`, `title_en`, `title_ar`, `instructions_en`, `instructions_ar`) VALUES ('asgn-les-2-4', 'les-2-4', 'CCQ Formulation Matrix', 'مصفوفة صياغة أسئلة فحص المفاهيم', 'Write 3 short Concept Checking Questions (with expected student answers) to verify comprehension of: \"Ali regrets having sold his car.\"', 'اكتب 3 أسئلة تحقق مفاهيمي قصيرة مع الإجابات المتوقعة للتأكد من فهم جملة: \"علي نادم على بيع سيارته\".');
INSERT INTO `lessons` (`id`, `module_id`, `number`, `slug`, `cefr`, `duration_min`, `title_en`, `title_ar`, `subtitle_en`, `subtitle_ar`, `pedagogical_overview_en`, `pedagogical_overview_ar`, `is_free_preview`) VALUES ('les-2-5', 'mod-2', '2.5', 'encouraging-participation', 'B1', 15, 'Encouraging Participation', 'تشجيع التفاعل والمشاركة الطلابية', 'Think-Pair-Share, strategic wait-time, and inviting shy or reticent learners', 'استراتيجية (فكر-زاوج-شارك)، إطالة زمن الانتظار، وإشراك الطلاب الخجولين بلباقة', 'Mary Budd Rowe’s seminal research revealed teachers typically wait only 0.9 seconds before answering their own questions. Extending wait-time to 3–5 seconds increases student responses by over 300\% and encourages reticent learners to participate.', 'أظهرت دراسات الدكتورة ماري باد رو أن المعلمين ينتظرون في المتوسط 0.9 ثانية فقط قبل الإجابة عن أسئلتهم بأنفسهم! تمديد وقت الانتظار إلى 3-5 ثوانٍ يضاعف استجابات الطلاب بنسبة 300\% ويشجع المترددين.', 0);
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-2-5', 'wait-time', '/ˈweɪt ˌtaɪm/', 'فترة الانتظار بعد طرح السؤال', 'Increase your wait-time so shy students can think.', 'زد فترة الانتظار ليتمكن الطلاب الخجولون من التفكير.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-2-5', 'reticent', '/ˈret.ɪ.sənt/', 'متردد أو قليل الكلام', 'Encourage reticent students with low-stakes questions.', 'شجع الطلاب المترددين بأسئلة سهلة لا تنطوي على مخاطرة.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-2-5', 'rehearse', '/rɪˈhɜːrs/', 'يتدرب ويهيئ الحديث مع زميله', 'Let students rehearse their answers in pairs first.', 'دع الطلاب يتدربون على إجاباتهم في أزواج أولاً.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-2-5', 'low-stakes', '/ˌloʊ ˈsteɪks/', 'قليل المخاطرة ولا يسبب حرجاً', 'Start discussions with low-stakes opinion questions.', 'ابدأ النقاش بأسئلة رأي سهلة لا تحمل إجابة خاطئة.');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-2-5-1', 'les-2-5', 'Take thirty seconds to think silently. Do not raise your hands yet.', 'خذوا ثلاثين ثانية للتفكير الصامت. لا ترفعوا أيديكم بعد.', '/teɪk ˈθɜːr.ti ˈsek.əndz/', 'Protected wait-time preventing dominant students from monopolizing.', 'حماية زمن التفكير تمنع الطلاب المندفعين من احتكار الحصة وتتيح للجميع الفرصة.', 'management');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-2-5-2', 'les-2-5', 'Turn to your neighbor. Share your thoughts for one minute before we open the floor.', 'التفتوا إلى زميلكم المجاور. شاركوا أفكاركم لمدة دقيقة قبل فتح باب النقاش العام.', '/tɜːrn tuː jɔːr ˈneɪ.bər/', 'Pair rehearsal stage providing low-risk rehearsal.', 'مرحلة التدريب الثنائي التي تمنح الطالب ثقة قبل التحدث أمام الفصل بأكمله.', 'instruction');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-2-5-3', 'les-2-5', 'I love how carefully you were listening, Salma. What did you and your partner discuss?', 'أعجبني إنصاتك وتركيزك يا سلمى. ما الذي ناقشتِه مع زميلتك؟', '/aɪ lʌv haʊ ˈkeər.fəl.i/', 'Gentle indirect nomination reducing performance anxiety.', 'مناداة لطيفة غير مباغتة تسأل عن نقاش الزملاء لتقليل التوتر.', 'feedback');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-5', 1, 'Teacher', 'المعلم', 'Why do you think the author chose the forest as the setting? Think silently for 10 seconds. No hands.', 'لماذا تعتقدون أن الكاتب اختار الغابة كمسرح للأحداث؟ فكروا بصمت لعشر ثوانٍ. بدون رفع الأيدي.');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-5', 2, 'Teacher', 'المعلم', 'Now, turn to your partner and test your theories.', 'والآن، التفتوا لزملائكم وناقشوا توقعاتكم.');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-5', 3, 'Class', 'الفصل', '(Lively paired discussions for 60 seconds)', '(نقاشات حية بين الأزواج لمدة دقيقة)');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-5', 4, 'Teacher', 'المعلم', 'Eyes back on me. Tarek, what did your partner say about the mystery?', 'انتباهكم إليّ من جديد. يا طارق، ما الذي قالته زميلتك عن الغموض في القصة؟');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-5', 5, 'Student', 'طالب', 'She said the forest makes everything feel dangerous and unknown.', 'قالت إن الغابة تجعل كل شيء يبدو محفوفاً بالخطر والغموض.');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-2-5', 6, 'Teacher', 'المعلم', 'What a poetic insight! Wonderful teamwork, you two.', 'يا له من استبصار بليغ ورائع! عمل جماعي ممتاز أنتما الاثنان.');
INSERT INTO `exercises` (`id`, `lesson_id`, `prompt_en`, `prompt_ar`, `context_en`, `context_ar`, `explanation_en`, `explanation_ar`, `source_reference`) VALUES ('ex-2-5-1', 'les-2-5', 'Why is the Think-Pair-Share technique particularly effective for lower-confidence second language learners?', 'لماذا تُعد استراتيجية (فكر-زاوج-شارك) فعالة جداً لطلاب اللغات ذوي الثقة المحدودة؟', 'In whole-class questioning, the same 3 extroverted students answer every time.', 'في الأسئلة العامة، يستحوذ نفس الطلاب الثلاثة المنطلقين على كل الإجابات.', 'Pair rehearsal reduces affective filter and anxiety, boosting participation rates across all proficiency bands.', 'التدريب الثنائي يقلل حاجز القلق والتردد النفسي، مما يرفع معدلات المشاركة لدى جميع المستويات.', 'Kagan, Cooperative Learning (Kagan Publishing)');
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-1', 'ex-2-5-1', 'Because it gives the teacher a 5-minute break to grade papers.', 'لأنها تمنح المعلم استراحة لتصحيح الدفاتر.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-2', 'ex-2-5-1', 'Because it offers individual processing time and a low-stakes rehearsal with one peer before whole-class scrutiny.', 'لأنها تتيح وقتاً للمعالجة الذهنية الفردية وتدريباً آمناً مع زميل واحد قبل مواجهة الفصل.', 1);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-3', 'ex-2-5-1', 'Because it eliminates the need to speak English.', 'لأنها تلغي الحاجة للتحدث بالإنجليزية.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-4', 'ex-2-5-1', 'Because it forces students to memorize the textbook answers.', 'لأنها تجبر الطلاب على حفظ إجابات الكتاب.', 0);
INSERT INTO `assignments` (`id`, `lesson_id`, `title_en`, `title_ar`, `instructions_en`, `instructions_ar`) VALUES ('asgn-les-2-5', 'les-2-5', 'Think-Pair-Share Lesson Plan', 'خطة تطبيق استراتيجية فكر-زاوج-شارك', 'Design an open-ended discussion question for a reading topic, specifying the exact time limits for the Think, Pair, and Share phases.', 'صمم سؤال نقاش مفتوح لنص قراءة مع تحديد التوقيت الدقيق لمراحل: فكر، زاوج، شارك.');
INSERT INTO `curriculum_modules` (`id`, `number`, `title_en`, `title_ar`, `cefr_range`, `color`, `description_en`, `description_ar`) VALUES ('mod-3', 3, 'Classroom Management & Giving Feedback', 'إدارة الفصل وتقديم التغذية الراجعة التربوية', 'A2–B2', '#16A34A', 'Master attention-getting routines, non-verbal de-escalation, gentle corrective feedback, growth-oriented praise, and student intrinsic motivation strategies.', 'إتقان بروتوكولات لفت الانتباه، واحتواء التشويش بدون صراخ، والتصحيح اللغوي البناء، والثناء المحفز للنمو، وإشعال الدافعية الذاتية للتعلم.');
INSERT INTO `lessons` (`id`, `module_id`, `number`, `slug`, `cefr`, `duration_min`, `title_en`, `title_ar`, `subtitle_en`, `subtitle_ar`, `pedagogical_overview_en`, `pedagogical_overview_ar`, `is_free_preview`) VALUES ('les-3-1', 'mod-3', '3.1', 'gaining-attention', 'A2', 15, 'Gaining Attention & Quiet', 'لفت الانتباه واستعادة الهدوء الصفي', 'Auditory cues, countdowns, and non-verbal presence versus shouting over noise', 'الإشارات الصوتية المتفق عليها، العد التنازلي، ولغة الجسد بدلاً من منافسة الضجيج بالصراخ', 'Shouting \"Quiet!\" teaches students that the teacher will compete with their noise. Doug Lemov and Harry Wong demonstrate that quiet signals (countdowns, clapping rhythms, or chime bells) preserve teacher vocal health and train students in self-regulation.', 'الصراخ بكلمة \"اسكتوا!\" يدرب الطلاب دون قصد على منافسة صوت المعلم. يوضح دوغ ليموف وهاري وونغ أن الإشارات الهادئة المتفق عليها (كالعد التنازلي أو إيقاعات التصفيق) تحمي حنجرة المعلم وتدرب الطلاب على الانضباط الذاتي.', 0);
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-3-1', 'countdown', '/ˈkaʊnt.daʊn/', 'العد التنازلي لاستعادة الهدوء', 'Use a five-second countdown to bring the room to silence.', 'استخدم عداً تنازلياً من خمس ثوانٍ ليعم الهدوء الفصل.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-3-1', 'call-and-response', '/ˌkɔːl ən rɪˈspɒns/', 'أسلوب النداء والاستجابة الجماعية', 'A call-and-response chant focuses attention instantly.', 'هتاف النداء والاستجابة يركز الانتباه على الفور.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-3-1', 'non-verbal', '/ˌnɒnˈvɜː.bəl/', 'غير لفظي / جسدي', 'Non-verbal cues are more powerful than shouting.', 'الإشارات غير اللفظية أكثر قوة وتأثيراً من الصراخ.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-3-1', 'stillness', '/ˈstɪl.nəs/', 'السكون والثبات الوقور', 'Stand in stillness until every student looks at you.', 'قف في ثبات تام حتى ينظر إليك كل طالب في الفصل.');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-3-1-1', 'les-3-1', 'Eyes on me in 3... 2... 1... and silence. Thank you.', 'انتباهكم إليّ خلال 3... 2... 1... وصمت تام. شكراً لكم.', '/aɪz ɒn miː ɪn θriː/', 'Universal countdown formula training prompt transition.', 'صيغة عد تنازلي قياسية تعود الطلاب على الاستجابة الفورية.', 'management');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-3-1-2', 'les-3-1', 'If you can hear my voice, clap once. If you can hear my voice, clap twice.', 'إذا كنتم تسمعون صوتي، صفقة واحدة. إذا كنتم تسمعون صوتي، صفقتين.', '/ɪf juː kæn hɪər maɪ vɔɪs/', 'Sensory acoustic filter drawing chatter into unison action.', 'فلتر حركي صوتي يحول الضوضاء المتفرقة إلى استجابة موحدة.', 'management');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-3-1-3', 'les-3-1', 'I am waiting for two desks in the back. Now we are ready.', 'أنا أنتظر طالبين في المقاعد الخلفية. الآن نحن جميعاً مستعدون.', '/aɪ æm ˈweɪ.tɪŋ fɔːr/', 'Positive peer pressure directing non-confrontational spotlight.', 'توجيه هادئ يستثمر تأثير الأقران دون تجريح مباشر.', 'management');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-3-1', 1, 'Class', 'الفصل', '(Loud talking after group work finishes)', '(أصوات مرتفعة بعد انتهاء العمل الجماعي)');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-3-1', 2, 'Teacher', 'المعلم', '(Raises right hand quietly) 5... 4... books closed... 3... 2... 1... and complete silence.', '(يرفع يده اليمنى بهدوء) 5... 4... الكتب مغلقة... 3... 2... 1... وصمت تام.');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-3-1', 3, 'Class', 'الفصل', '(Noise drops instantly; all eyes on teacher)', '(ينخفض الصوت تماماً؛ وتتجه الأنظار للمعلم)');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-3-1', 4, 'Teacher', 'المعلم', 'Thank you group three, thank you group one. Excellent self-control.', 'شكراً للمجموعة الثالثة، شكراً للمجموعة الأولى. انضباط ذاتي ممتاز.');
INSERT INTO `exercises` (`id`, `lesson_id`, `prompt_en`, `prompt_ar`, `context_en`, `context_ar`, `explanation_en`, `explanation_ar`, `source_reference`) VALUES ('ex-3-1-1', 'les-3-1', 'Why is raising your voice and shouting \"BE QUIET!\" pedagogically counterproductive?', 'لماذا يُعد الصراخ ورفع الصوت طلباً للهدوء أمراً غير منتج ومضر تربوياً؟', 'The classroom is noisy during an energetic speaking exercise.', 'الفصل يشهد ضجيجاً أثناء نشاط محادثة حماسي.', 'Calm, non-verbal signals and rhythmic countdowns establish psychological containment without escalating room tension.', 'الإشارات الهادئة والعد التنازلي الرصين يصنعان احتواءً نفسياً دون تصعيد التوتر في الغرفة الصفية.', 'Harry Wong, The First Days of School');
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-1', 'ex-3-1-1', 'Because students will laugh at your accent.', 'لأن الطلاب سيضحكون من لكنتك.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-2', 'ex-3-1-1', 'Because it raises classroom decibel levels, increases teacher vocal strain, and normalizes yelling as the only standard of compliance.', 'لأنه يرفع مستوى الضوضاء العام، ويرهق حبال المعلم الصوتية، ويجعل الصراخ هو المعيار الوحيد للاستجابة.', 1);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-3', 'ex-3-1-1', 'Because you are not allowed to speak English loudly.', 'لأنه غير مسموح بالتحدث بالإنجليزية بصوت مرتفع.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-4', 'ex-3-1-1', 'Because it takes too much time.', 'لأنه يستغرق وقتاً طويلاً جداً.', 0);
INSERT INTO `assignments` (`id`, `lesson_id`, `title_en`, `title_ar`, `instructions_en`, `instructions_ar`) VALUES ('asgn-les-3-1', 'les-3-1', 'Attention-Signal Implementation Protocol', 'بروتوكول تطبيق إشارة جذب الانتباه', 'Write down a script of how you will teach your students a new attention signal (e.g. countdown or chime) on day one.', 'اكتب نصاً يشرح كيف ستدرب طلابك على إشارة جذب انتباه جديدة (كالعد أو الجرس) في اليوم الأول.');
INSERT INTO `lessons` (`id`, `module_id`, `number`, `slug`, `cefr`, `duration_min`, `title_en`, `title_ar`, `subtitle_en`, `subtitle_ar`, `pedagogical_overview_en`, `pedagogical_overview_ar`, `is_free_preview`) VALUES ('les-3-2', 'mod-3', '3.2', 'handling-disruptions', 'B1', 20, 'Handling Disruptions Calmly', 'التعامل مع التشويش والمقاطعات بهدوء واحتواء', 'Proximity control, private whispers, and avoiding public power struggles', 'التحكم بالاقتراب المكاني، والتوجيه الفردي الهامس، وتجنب صراع القوى العلني', 'Publicly reprimanding a teenager often invites a public fight to save face. Bill Rogers emphasizes \"least intrusive intervention\": proximity, non-verbal cues, and a quiet private word preserve dignity while maintaining firm boundaries.', 'التوبيخ العلني للطالب المراهق يدفعه غالباً للمكابرة دفاعاً عن ماء وجهه أمام زملائه. يؤكد الدكتور بيل روجرز على مبدأ \"التدخل الأقل إزعاجاً\": الاقتراب الهادئ، والهمس الفردي، مع الحزم التربوي.', 0);
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-3-2', 'proximity', '/prɒkˈsɪm.ə.ti/', 'الاقتراب المكاني من الطالب', 'Use proximity control by standing near the chatting students.', 'استخدم الاقتراب المكاني بالوقوف بالقرب من الطلاب المتحدثين.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-3-2', 'power struggle', '/ˈpaʊ.ər ˌstrʌɡ.əl/', 'صراع القوى والجدال العقيم', 'Never enter a public power struggle in front of peers.', 'لا تدخل أبداً في صراع قوى علني أمام الزملاء.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-3-2', 'de-escalate', '/diːˈes.kə.leɪt/', 'يهدئ الموقف وينزع فتيل التوتر', 'A calm, low tone de-escalates tense moments.', 'النبرة الهادئة والمنخفضة تنزع فتيل المواقف المتوترة.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-3-2', 'dignity', '/ˈdɪɡ.nə.ti/', 'الكرامة الإنسانية للتعلم', 'Correct behavioral issues while protecting the student’s dignity.', 'عالج المشكلات السلوكية مع حماية كرامة الطالب.');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-3-2-1', 'les-3-2', 'Hossam, I need your notebook open on exercise 2. Thank you.', 'يا حسام، أحتاج منك فتح دفترك على التمرين 2. شكراً لك.', '/aɪ niːd jɔːr ˈnoʊt.bʊk ˈoʊ.pən/', 'Presumptive positive compliance with polite closing gratitude.', 'افتراض مسبق للاستجابة الإيجابية يتبعه شكر فوري يغلق باب الجدال.', 'management');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-3-2-2', 'les-3-2', '(Quiet whisper close to student) Is everything alright? Focus here with us.', '(همس فردي هادئ بجانب الطالب) هل كل شيء على ما يرام؟ ركز معنا هنا.', '/ɪz ˈev.ri.θɪŋ ɔːlˈraɪt/', 'Discreet empathetic intervention preventing public defiance.', 'تدخل سري عطوف يقطع الشرود دون إشعار بقية الفصل بالمشكلة.', 'management');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-3-2-3', 'les-3-2', 'You have a choice: join the discussion actively, or we talk after class. I trust you will choose well.', 'لديك خيار: إما المشاركة بفاعلية في النقاش، أو نتحدث سوياً بعد الحصة. وأنا أثق بحسن اختيارك.', '/juː hæv ə tʃɔɪs/', 'Structured choice transferring accountability to the learner.', 'تخيير منظم يحمل الطالب مسؤولية قراره ويمنحه مخرجاً كريماً.', 'management');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-3-2', 1, 'Teacher', 'المعلم', '(Notice two students whispering at the back while teaching; walks smoothly toward their desks while continuing to explain the reading)', '(يلاحظ طالبين يتهامسان في الخلف؛ فيتحرك بانسيابية نحوهما مع مواصلة الشرح)');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-3-2', 2, 'Teacher', 'المعلم', '...and so the explorer reached the summit in 1953. (Lightly taps the corner of their desk and makes eye contact with a warm smile)', '...وهكذا وصل المستكشف للقمة عام 1953. (ينقر بخفة على زاوية مكتبهما ويتواصل بصرياً بابتسامة دافئة)');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-3-2', 3, 'Student', 'طالب', '(Immediately opens his book and stops talking)', '(يفتح كتابه على الفور ويتوقف عن الكلام)');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-3-2', 4, 'Teacher', 'المعلم', 'Thank you. Who can tell me what obstacle the team faced next?', 'شكراً لكما. من يخبرنا ما هي العقبة التالية التي واجهت الفريق؟');
INSERT INTO `exercises` (`id`, `lesson_id`, `prompt_en`, `prompt_ar`, `context_en`, `context_ar`, `explanation_en`, `explanation_ar`, `source_reference`) VALUES ('ex-3-2-1', 'les-3-2', 'What is the \"least intrusive intervention\" principle in classroom behavior management?', 'ما هو مبدأ \"التدخل الأقل إزعاجاً\" في إدارة السلوك الصفي وفق مدرسة بيل روجرز؟', 'A student is tapping their pen and looking out the window while you explain a task.', 'طالب ينقر بقلمه وينظر من النافذة أثناء شرحك للمهمة.', 'Subtle, low-profile intervention handles minor disengagement without derailing the learning momentum of other students.', 'التدخل الهادئ يعالج التشتت دون التضحية بتركيز بقية طلاب الفصل أو تصعيد المشكلة.', 'Bill Rogers, Classroom Behaviour: A Practical Guide to Effective Teaching');
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-1', 'ex-3-2-1', 'Send the student to the principal’s office immediately.', 'طرد الطالب فوراً لمكتب المدير.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-2', 'ex-3-2-1', 'Address the behavior with the minimum intervention necessary (proximity or a gentle non-verbal signal) so learning flow is not broken.', 'معالجة السلوك بأقل قدر ممكن من الإزعاج (كالاقتراب المكاني أو إشارة لطيفة) لعدم قطع تدفق التعلم.', 1);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-3', 'ex-3-2-1', 'Stop the entire lesson and make the student apologize in front of everyone.', 'إيقاف الحصة بالكامل وإجبار الطالب على الاعتذار أمام الجميع.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-4', 'ex-3-2-1', 'Throw a piece of chalk at the desk.', 'إلقاء قطعة طباشير نحو المكتب.', 0);
INSERT INTO `assignments` (`id`, `lesson_id`, `title_en`, `title_ar`, `instructions_en`, `instructions_ar`) VALUES ('asgn-les-3-2', 'les-3-2', 'De-escalation Case Study Script', 'سيناريو احتواء ونزع فتيل التوتر', 'Write a 4-line script handling a teenager who rolls their eyes and refuses to open their workbook.', 'اكتب حواراً من 4 أسطر تعالج فيه بأسلوب تربوي موقف طالب مراهق يبدي تبرماً ويرفض فتح الكتاب.');
INSERT INTO `lessons` (`id`, `module_id`, `number`, `slug`, `cefr`, `duration_min`, `title_en`, `title_ar`, `subtitle_en`, `subtitle_ar`, `pedagogical_overview_en`, `pedagogical_overview_ar`, `is_free_preview`) VALUES ('les-3-3', 'mod-3', '3.3', 'positive-reinforcement', 'A2', 15, 'Positive Reinforcement', 'التعزيز الإيجابي والثناء التربوي المحفز', 'Process praise over generic praise, and Carol Dweck’s growth mindset vocabulary', 'الثناء على الجهد والعمليات بدلاً من المدح العشوائي، ومصطلحات عقلية النمو لكارول دويك', 'Praising innate intelligence (\"You are so smart!\") actually creates fear of failure. Dr. Carol Dweck’s research proves that praising strategy, persistence, and revision (\"I love how you checked your spelling\") inspires resilience and long-term achievement.', 'مدح الذكاء الفطري (\"أنت ذكي جداً!\") يولد لدى الطالب خوفاً من ارتكاب الأخطاء وفقدان هذا اللقب. أثبتت أبحاث الدكتورة كارول دويك أن مدح الجهد والاستراتيجية (\"أعجبني تدقيقك في كتابة الكلمات\") ينمي المثابرة والتفوق المستدام.', 0);
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-3-3', 'reinforcement', '/ˌriː.ɪnˈfɔːrs.mənt/', 'التعزيز التربوي', 'Positive reinforcement builds lasting motivation.', 'التعزيز الإيجابي يصنع دافعية مستمرة.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-3-3', 'growth mindset', '/ˌɡroʊθ ˈmaɪnd.set/', 'عقلية النمو والتطور', 'Praise effort to cultivate a growth mindset.', 'امدح الجهد لترسيخ عقلية النمو.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-3-3', 'perseverance', '/ˌpɜː.sɪˈvɪə.rəns/', 'المثابرة والإصرار', 'Acknowledge their perseverance on hard questions.', 'أشِد بمثابرتهم في حل الأسئلة الصعبة.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-3-3', 'specific', '/spəˈsɪf.ɪk/', 'محدد ودقيق', 'Give specific praise describing exactly what was well done.', 'قدم ثناءً محدداً يصف بالضبط ما تم إنجازه بإتقان.');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-3-3-1', 'les-3-3', 'I love how you used three different descriptive adjectives in that sentence. That is rich writing!', 'أعجبني جداً استخدامك لثلاث صفات وصفية متنوعة في تلك الجملة. هذه كتابة ثرية حقاً!', '/aɪ lʌv haʊ juː juːzd/', 'Specific process praise identifying exact academic merit.', 'ثناء نوعي محدد يبرز العنصر الإبداعي الأكاديمي الذي يستحق الإشادة.', 'feedback');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-3-3-2', 'les-3-3', 'That was a tricky problem, but you did not give up. Look at your progress between draft 1 and draft 2!', 'كانت مسألة صعبة ومليئة بالتحدي، لكنك لم تستسلم. انظر للتطور الهائل بين مسودتك الأولى والثانية!', '/ðæt wɒz ə ˈtrɪk.i ˈprɒb.ləm/', 'Growth mindset encouragement spotlighting iterative revision.', 'تحفيز يرسخ عقلية النمو ويوضح قيمة المحاولة والمراجعة المستمرة.', 'feedback');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-3-3-3', 'les-3-3', 'Notice how table four started immediately without wasting a single second. Superb work ethic!', 'لاحظوا كيف بدأت المجموعة الرابعة العمل فوراً دون إضاعة ثانية واحدة. روح عمل واجتهاد رائعة!', '/ˈnoʊ.tɪs haʊ ˈteɪ.bəl fɔːr/', 'Public behavioral narration encouraging peer imitation.', 'وصف إيجابي لسلوك مثالي يحفز بقية الفصل على الاقتداء به.', 'management');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-3-3', 1, 'Student', 'طالب', 'Teacher, I wrote this paragraph, but I made four grammar mistakes in my first attempt.', 'أستاذ، كتبت هذه الفقرة، لكنني ارتكبت أربعة أخطاء نحوية في محاولتي الأولى.');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-3-3', 2, 'Teacher', 'المعلم', 'Mistakes are proof that you are learning! Look at how you self-corrected three of them when you re-read. That shows true linguistic maturity.', 'الأخطاء دليل قاطع على أنك تتعلم! انظر كيف قمت بتصحيح ثلاثة منها بنفسك عند إعادة القراءة. هذا يدل على نضج لغوي حقيقي.');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-3-3', 3, 'Student', 'طالب', 'Really? I thought making mistakes meant I was bad at English.', 'حقاً؟ كنت أظن أن الخطأ يعني أنني ضعيف في الإنجليزية.');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-3-3', 4, 'Teacher', 'المعلم', 'Never! Growth comes through fixing errors. Keep that curious mindset!', 'أبداً! النمو الحقيقي يأتي من معالجة الأخطاء وتجاوزها. حافظ على هذه الروح!');
INSERT INTO `exercises` (`id`, `lesson_id`, `prompt_en`, `prompt_ar`, `context_en`, `context_ar`, `explanation_en`, `explanation_ar`, `source_reference`) VALUES ('ex-3-3-1', 'les-3-3', 'According to Carol Dweck’s research on praise and mindset, which phrase is most beneficial to long-term student development?', 'وفق أبحاث الدكتورة كارول دويك حول الثناء وعقلية النمو، أي العبارات التالية هي الأكثر نفعاً لتطور الطالب؟', 'A student successfully completes a challenging listening task after two failed attempts.', 'أنجز طالب نشاط استماع صعباً بعد محاولتين غير موفقتين.', 'Process praise targets effort, strategy, and perseverance, instilling resilience rather than fear of failure.', 'الثناء على خطوات العمل والمثابرة يبني الصلابة النفسية ويحفز الطالب على خوض التحديات المعرفية.', 'Carol Dweck, Mindset: The New Psychology of Success');
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-1', 'ex-3-3-1', 'You are a natural genius! Nobody else could do that.', 'أنت عبقري بالفطرة! لا أحد غيرك يستطيع حل ذلك.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-2', 'ex-3-3-1', 'I am so impressed by your determination; you listened for the keywords and adapted your strategy until it worked.', 'أنا فخور بإصرارك ومثابرتك؛ أنصتّ للكلمات المفتاحية وطوّرت خطتك حتى نجحت.', 1);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-3', 'ex-3-3-1', 'See? It was so easy, you should not have struggled.', 'رأيت؟ كان الأمر في غاية السهولة ولم يكن يستحق كل هذا العناء.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-4', 'ex-3-3-1', 'Good boy, sit down.', 'شاطر، اجلس مكانك.', 0);
INSERT INTO `assignments` (`id`, `lesson_id`, `title_en`, `title_ar`, `instructions_en`, `instructions_ar`) VALUES ('asgn-les-3-3', 'les-3-3', 'Effort-Focused Feedback Conversion', 'تحويل الثناء التقليدي لثناء قائم على الجهد', 'Rewrite the following generic praises into process praise: 1. \"You are very smart.\" 2. \"Good presentation.\" 3. \"Nice drawing.\"', 'أعد صياغة العبارات التقليدية الثلاث التالية إلى عبارات ثناء نوعية تركز على الجهد والخطوات.');
INSERT INTO `lessons` (`id`, `module_id`, `number`, `slug`, `cefr`, `duration_min`, `title_en`, `title_ar`, `subtitle_en`, `subtitle_ar`, `pedagogical_overview_en`, `pedagogical_overview_ar`, `is_free_preview`) VALUES ('les-3-4', 'mod-3', '3.4', 'correcting-errors', 'B2', 20, 'Correcting Errors Kindly & Constructively', 'تصحيح الأخطاء بلباقة وأسلوب تربوي بناء', 'Balancing fluency vs accuracy: finger correction, delayed feedback, and peer editing', 'الموازنة بين الطلاقة والدقة: التصحيح بالأصابع، التغذية الراجعة المؤجلة، وتصويب الأقران', 'Interrupting a student mid-sentence during a fluency activity destroys communication and confidence. Adrian Underhill and Jeremy Harmer advocate for \"delayed feedback\": the teacher notes down errors silently, writes them anonymously on the board afterwards, and has the class edit them collectively.', 'مقاطعة الطالب في منتصف حديثه أثناء نشاط طلاقة يهدم ثقته ورغبته في التعبير. يوصي الخبراء بـ \"التغذية الراجعة المؤجلة\": يدون المعلم الأخطاء في مفكرته بصمت، ثم يكتبها على السبورة دون أسماء ليصححها الجميع معاً.', 0);
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-3-4', 'fluency', '/ˈfluː.ən.si/', 'الطلاقة والانسيابية في الحديث', 'Focus on fluency during free speaking practice.', 'ركز على الطلاقة أثناء محادثات التحدث الحر.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-3-4', 'accuracy', '/ˈæk.jʊ.rə.si/', 'الدقة اللغوية وصحة التراكيب', 'Check for accuracy during the grammar exercise.', 'تحقق من الدقة أثناء تمرين القواعد.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-3-4', 'delayed feedback', '/dɪˈleɪd ˈfiːd.bæk/', 'التغذية الراجعة المؤجلة', 'Delayed feedback keeps fluency discussions flowing.', 'التغذية الراجعة المؤجلة تحافظ على انسيابية النقاشات.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-3-4', 'finger correction', '/ˈfɪŋ.ɡər kəˈrek.ʃən/', 'التصحيح باستخدام الأصابع للإشارة للكلمة الناقصة', 'Use finger correction to indicate a missing auxiliary verb.', 'استخدم الأصابع للإشارة إلى موضع الفعل المساعد الناقص.');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-3-4-1', 'les-3-4', 'Almost! Listen to your verb ending: \"Yesterday he GO...?\" Try again, Nour.', 'أوشكتِ على الصواب! أنصتي لنهاية الفعل: \"Yesterday he GO...؟\" حاولي ثانية يا نور.', '/ˈɔːl.moʊst ˈlɪs.ən tuː/', 'Echo prompt with rising intonation cueing self-correction.', 'ترديد الكلمة بنبرة تساؤل تصاعدية تحفز الطالب على تصحيح نفسه ذاتياً.', 'feedback');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-3-4-2', 'les-3-4', 'Look at my five fingers. Each finger is a word: \"She... is... not... ready.\" Where did the word slip?', 'انظروا إلى أصابعي الخمسة. كل إصبع يمثل كلمة: \"She... is... not... ready.\" أين سقطت الكلمة؟', '/lʊk æt maɪ faɪv ˈfɪŋ.ɡərz/', 'Tactile finger correction providing spatial grammar scaffolding.', 'تصحيح حركي ملموس بالأصابع يحدد موقع الخلل القواعدي دون كلام محرج.', 'instruction');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-3-4-3', 'les-3-4', 'Here are three lovely phrases I overheard. Let us polish them together on the board.', 'هذه ثلاث عبارات جميلة التقطتها من نقاشاتكم الرائعة. دعونا نصقلها ونطورها معاً على السبورة.', '/hɪər ɑːr θriː ˈlʌv.li ˈfreɪ.zɪz/', 'Non-threatening framing introducing delayed error correction.', 'مدخل دافئ وودي لتقديم تصحيح الأخطاء المؤجل بروح التعاون.', 'feedback');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-3-4', 1, 'Student', 'طالب', 'In my opinion, people which lives in cities are more stressed.', 'في رأيي، الناس الذي يعيشون في المدن أكثر توتراً.');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-3-4', 2, 'Teacher', 'المعلم', '(Nods warmly to encourage flow) Interesting point! (After student finishes speaking) You said: \"People WHICH lives\". If we speak about humans, do we use which, or who?', '(يومئ بلطف لتشجيعه على الإكمال) نقطة مثيرة! (بعد انتهاء الطالب) قلت: \"الناس التي يعيشون\". حين نتحدث عن البشر، هل نستخدم which أم who؟');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-3-4', 3, 'Student', 'طالب', 'Ah! People WHO live!', 'آه! الناس الذين يعيشون!');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-3-4', 4, 'Teacher', 'المعلم', 'Spot on! Beautiful recovery. Continue your thoughts.', 'أحسنت تماماً! تصويب ذاتي رائع. أكمل فكرتك القيمة.');
INSERT INTO `exercises` (`id`, `lesson_id`, `prompt_en`, `prompt_ar`, `context_en`, `context_ar`, `explanation_en`, `explanation_ar`, `source_reference`) VALUES ('ex-3-4-1', 'les-3-4', 'During a 10-minute student debate (fluency focus), a student says \"He don’t know nothing.\" What should the teacher do?', 'أثناء مناظرة طلابية مدتها 10 دقائق (تركز على الطلاقة)، قال طالب \"He don’t know nothing\". ماذا يجب على المعلم فعله؟', 'The class is deeply engaged in expressing opinions on environmental conservation.', 'الطلاب مندمجون تماماً في التعبير عن آرائهم حول حماية البيئة.', 'In fluency stages, uninterrupted communication comes first. Delayed feedback corrects language without shattering speaker flow.', 'في مراحل تدريب الطلاقة، تدفق الأفكار هو الأولوية الأولى. التغذية الراجعة المؤجلة تعالج الخطأ دون تحطيم ثقة المتحدث.', 'Harmer, The Practice of English Language Teaching & CELTA Guidelines');
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-1', 'ex-3-4-1', 'Stop the debate immediately, make the student repeat the rule five times, and deduct points.', 'إيقاف المناظرة فوراً، وإجبار الطالب على تكرار القاعدة خمس مرات، وخصم درجات.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-2', 'ex-3-4-1', 'Jot down the sentence in a teaching notebook without interrupting the speaker, and analyze it with the whole class during delayed feedback.', 'تدوين الجملة في مفكرة المعلم دون مقاطعة المتحدث، ومناقشتها مع الفصل لاحقاً خلال جلسة التصحيح المؤجل.', 1);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-3', 'ex-3-4-1', 'Laugh loudly so other students notice the double negative.', 'الضحك بصوت عالٍ لينتبه الطلاب لوجود نفي مكرر.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-4', 'ex-3-4-1', 'Never correct grammar errors under any circumstances.', 'عدم تصحيح الأخطاء النحوية مطلقاً.', 0);
INSERT INTO `assignments` (`id`, `lesson_id`, `title_en`, `title_ar`, `instructions_en`, `instructions_ar`) VALUES ('asgn-les-3-4', 'les-3-4', 'Delayed Feedback Board Layout', 'تخطيط سبورة التغذية الراجعة المؤجلة', 'Write out 4 ungrammatical sentences heard in an A2 classroom and design how you will present them on the board for a collaborative correction clinic.', 'اكتب 4 جمل تحتوي أخطاء شائعة في مستوى A2 وصمم طريقة عرضها على السبورة في ورشة تدريبية مشتركة لتصويب الأخطاء.');
INSERT INTO `lessons` (`id`, `module_id`, `number`, `slug`, `cefr`, `duration_min`, `title_en`, `title_ar`, `subtitle_en`, `subtitle_ar`, `pedagogical_overview_en`, `pedagogical_overview_ar`, `is_free_preview`) VALUES ('les-3-5', 'mod-3', '3.5', 'motivating-students', 'B1', 20, 'Motivating Students & Building Confidence', 'تحفيز الطلاب وبناء الثقة اللغوية المستدامة', 'Intrinsic drivers, gamification principles, relevance, and creating a safe speaking sanctuary', 'الدوافع الذاتية، مبادئ التعلم باللعب، ربط المحتوى بالواقع، وجعل الفصل ملاذاً آمناً للممارسة', 'Extrinsic rewards (candies, grades) lose power rapidly and can even undermine intrinsic curiosity. Zoltan Dornyei’s motivational framework underscores relevance, self-efficacy, and autonomy: when students see English as their personal voice in the world, motivation becomes limitless.', 'المكافآت الخارجية المادية (كالحلوى والدرجات) تفقد بريقها سريعاً وتضعف الشغف الأصيل. يوضح البروفيسور زولتان دورنيي أن محركات الدافعية الحقيقية تكمن في الجدوى، والاستقلالية، وثقة الفرد بقدرته؛ حين يرى الطالب الإنجليزية صوته الشخصي للعالم، تشتعل دوافعه تلقائياً.', 0);
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-3-5', 'intrinsic', '/ɪnˈtrɪn.zɪk/', 'دافعي ذاتي نابع من الداخل', 'Intrinsic motivation lasts far longer than extrinsic rewards.', 'الدافعية الذاتية تدوم أطول بكثير من المكافآت الخارجية.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-3-5', 'relevance', '/ˈrel.ə.vəns/', 'الجدوى والصلة بالواقع المعاش', 'Show the direct relevance of this grammar to real social media.', 'بين الصلة المباشرة بين هذه القواعد واستخدامات وسائل التواصل الواقعية.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-3-5', 'sanctuary', '/ˈsæŋk.tʃʊə.ri/', 'ملاذ آمن مطمئن', 'Make the classroom a psychological sanctuary for free expression.', 'اجعل الفصل ملاذاً نفسياً آمناً للتعبير الحر.');
INSERT INTO `vocabulary` (`lesson_id`, `word_en`, `phonetic`, `meaning_ar`, `example_en`, `example_ar`) VALUES ('les-3-5', 'gamification', '/ˌɡeɪ.mɪ.fɪˈkeɪ.ʃən/', 'التلعيب وتطبيق آليات الألعاب في التعليم', 'Cooperative gamification unites students toward common goals.', 'التلعيب التعاوني يوحد الطلاب نحو تحقيق أهداف مشتركة.');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-3-5-1', 'les-3-5', 'In this classroom, mistakes are not embarrassing; they are our stepping stones to greatness.', 'في هذا الفصل، الأخطاء ليست مدعاة للحرج؛ بل هي جسورنا الحقيقية نحو التميز والإتقان.', '/ɪn ðɪs ˈklɑːs.ruːm mɪsˈteɪks/', 'Psychological safety declaration transforming classroom climate.', 'إعلان تربوي يصنع الأمان النفسي ويحرر الطلاب من عقدة الخوف من الخطأ.', 'management');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-3-5-2', 'les-3-5', 'You are not just learning grammar rules; you are discovering your international voice.', 'أنتم لا تدرسون مجرد قواعد نظرية؛ أنتم تكتشفون صوتكم الشخصي الذي يخاطب العالم.', '/juː ɑːr nɒt dʒʌst ˈlɜːr.nɪŋ/', 'Inspirational empowerment reframing language acquisition.', 'خطاب تحفيزي يعيد تعريف تعلم اللغة كقوة تمكين شخصية وحضارية.', 'transition');
INSERT INTO `expressions` (`id`, `lesson_id`, `english`, `arabic`, `phonetic_tip`, `pedagogical_note_en`, `pedagogical_note_ar`, `category`) VALUES ('exp-3-5-3', 'les-3-5', 'Look back at where you were in September. You can now hold a full 5-minute conversation! Be proud of that.', 'تذكروا أين كنتم في بداية العام الدراسي. أنتم الآن قادرون على إدارة محادثة كاملة لـ 5 دقائق! يحق لكم أن تفخروا بذلك.', '/lʊk bæk æt weər juː wɜːr/', 'Longitudinal self-comparison building deep self-efficacy.', 'مقارنة إيجابية مع الذات في الماضي ترسخ الشعور بالإنجاز والقدرة.', 'feedback');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-3-5', 1, 'Student', 'طالب', 'Teacher, English is so difficult. I am scared I will never speak like native speakers.', 'أستاذ، اللغة الإنجليزية صعبة جداً. أخشى أنني لن أتحدث أبداً بطلاقة كالمتحدثين الأصليين.');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-3-5', 2, 'Teacher', 'المعلم', 'Your goal is not to sound like someone else; your goal is to express YOUR brilliant ideas clearly in international English.', 'هدفك ليس أن تقلد شخصاً آخر؛ هدفك هو التعبير عن أفكارك النيرة بوضوح بلغة إنجليزية عالمية.');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-3-5', 3, 'Student', 'طالب', 'So having an accent does not mean I am failing?', 'إذن وجود لكنة لا يعني أنني فاشل؟');
INSERT INTO `dialogues` (`lesson_id`, `sort_order`, `speaker`, `speaker_ar`, `en`, `ar`) VALUES ('les-3-5', 4, 'Teacher', 'المعلم', 'An accent is proof of your courage and culture! Be proud of it, speak clearly, and never stay silent.', 'اللكنة دليل شجاعتك وتنوعك الثقافي! اعتز بها، وتحدث بوضوح، ولا تدع الخوف يسكِتك أبداً.');
INSERT INTO `exercises` (`id`, `lesson_id`, `prompt_en`, `prompt_ar`, `context_en`, `context_ar`, `explanation_en`, `explanation_ar`, `source_reference`) VALUES ('ex-3-5-1', 'les-3-5', 'According to Zoltan Dornyei’s Motivational Strategies in the Language Classroom, which approach best builds long-term student engagement?', 'وفق استراتيجيات البروفيسور زولتان دورنيي لتحفيز دارسي اللغات، أي المداخل التالية هو الأفضل لبناء اندماج مستدام؟', 'High school students view English as a chore for examinations only.', 'طلاب المرحلة الثانوية يرون الإنجليزية مجرد عبء للامتحانات المدرسية فقط.', 'Personal relevance and future self-guides cultivate authentic intrinsic motivation that outlasts test deadlines.', 'الجدوى الشخصية وبناء صورة الذات المستقبلية يصنعان دافعية ذاتية أصيلة تتجاوز حدود الامتحانات.', 'Zoltan Dornyei, Motivational Strategies in the Language Classroom (Cambridge University Press)');
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-1', 'ex-3-5-1', 'Threatening to fail anyone who scores below 70\%.', 'التهديد برسوب أي طالب يحصل على أقل من 70\%.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-2', 'ex-3-5-1', 'Connecting classroom topics to their personal identities, career aspirations, and genuine communicative purposes.', 'ربط موضوعات الحصص بهوياتهم الشخصية، وطموحاتهم المهنية، والأهداف التواصلية الحقيقية.', 1);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-3', 'ex-3-5-1', 'Promising chocolate for every correct grammar answer.', 'الوعد بقطع شوكولاتة لكل إجابة قواعد صحيحة.', 0);
INSERT INTO `exercise_options` (`id`, `exercise_id`, `text_en`, `text_ar`, `is_correct`) VALUES ('opt-4', 'ex-3-5-1', 'Doubling homework assignments every week.', 'مضاعفة الواجبات المنزلية كل أسبوع.', 0);
INSERT INTO `assignments` (`id`, `lesson_id`, `title_en`, `title_ar`, `instructions_en`, `instructions_ar`) VALUES ('asgn-les-3-5', 'les-3-5', 'Personalized English Vision Project', 'مشروع رؤية الطالب اللغوية المستقبلية', 'Design a 5-minute warm-up activity where students write and share 3 ways English will empower their dream future profession.', 'صمم نشاط تهيئة من 5 دقائق يكتب فيه الطلاب ويشاركون 3 طرق ستدعم بها الإنجليزية مهنتهم المستقبلية المنشودة.');
